(426,11,1,'possible','possible','possible','medium','{\"strengths\":[\"DNSC student\",\"Enrolling for first year\"],\"concerns\":[\"Unpublished GWA requirement\"],\"reminders\":[\"Check with DNSC Scholarship Unit\",\"Prepare latest grades and COR\"]}',69,'[{\"key\":\"dnsc\",\"label\":\"DNSC student (current or incoming)\",\"result\":\"pass\",\"detail\":\"Your BAKR account is for a DNSC student.\",\"required\":true},{\"key\":\"enrolled\",\"label\":\"Currently enrolled or enrolling\",\"result\":\"pass\",\"detail\":\"Your answer: Incoming first-year (not yet started).\",\"required\":true},{\"key\":\"gwa\",\"label\":\"Meets the academic (GWA) requirement\",\"result\":\"confirm\",\"detail\":\"Set by the DNSC Scholarship and Grants Unit. It is not published in the sources BAKR uses.\",\"required\":true}]','You may qualify for the DNSC Academic Scholarship depending on the institutional GWA cut-off. Please verify your Grade 12 average with the DNSC Scholarship and Grants Unit.','gemini','2026-11-19 04:37:28','2026-11-19 04:37:18','2026-11-19 04:37:28'),
(427,11,2,'not_eligible','not_eligible','not_eligible','low','{\"strengths\":[\"DNSC incoming student\"],\"concerns\":[\"No music, dance, arts, or sports skill\"],\"reminders\":[]}',36,'[{\"key\":\"dnsc\",\"label\":\"DNSC student (current or incoming)\",\"result\":\"pass\",\"detail\":\"Your BAKR account is for a DNSC student.\",\"required\":true},{\"key\":\"enrolled\",\"label\":\"Currently enrolled or enrolling\",\"result\":\"pass\",\"detail\":\"Your answer: Incoming first-year (not yet started).\",\"required\":true},{\"key\":\"talent\",\"label\":\"Has a skill in music, dance, arts, or sports\",\"result\":\"fail\",\"detail\":\"None of the qualifying options were selected.\",\"required\":true},{\"key\":\"awards\",\"label\":\"Has awards or achievements to show\",\"result\":\"unknown\",\"detail\":\"Answer this in your application so BAKR can check it.\",\"required\":false}]','You are not eligible for this Grant-in-Aid because it requires specific skills in music, dance, arts, or sports, which were not selected in your application.','gemini','2026-11-19 04:37:28','2026-11-19 04:37:18','2026-11-19 04:37:28'),
(428,11,3,'not_eligible','not_eligible','not_eligible','low','{\"strengths\":[\"DNSC incoming student\"],\"concerns\":[\"Requires current enrollment\",\"Not a student leader\"],\"reminders\":[]}',25,'[{\"key\":\"dnsc\",\"label\":\"DNSC student (current or incoming)\",\"result\":\"pass\",\"detail\":\"Your BAKR account is for a DNSC student.\",\"required\":true},{\"key\":\"enrolled\",\"label\":\"Currently enrolled\",\"result\":\"fail\",\"detail\":\"Your answer: Incoming first-year (not yet started).\",\"required\":true},{\"key\":\"leader\",\"label\":\"Student Supreme Council officer or Student Publication Editorial Board member\",\"result\":\"fail\",\"detail\":\"None of the qualifying options were selected.\",\"required\":true}]','You are not eligible for this scholarship because it is reserved for currently enrolled student council officers or editorial board members.','gemini','2026-11-19 04:37:28','2026-11-19 04:37:18','2026-11-19 04:37:28'),
(429,11,4,'possible','possible','possible','high','{\"strengths\":[\"Willing to work as student assistant\",\"Low family income\"],\"concerns\":[\"Financial need assessment by unit\"],\"reminders\":[\"Bring proof of family income\",\"Prepare student ID and COR\"]}',91,'[{\"key\":\"dnsc\",\"label\":\"DNSC student (current or incoming)\",\"result\":\"pass\",\"detail\":\"Your BAKR account is for a DNSC student.\",\"required\":true},{\"key\":\"enrolled\",\"label\":\"Currently enrolled or enrolling\",\"result\":\"pass\",\"detail\":\"Your answer: Incoming first-year (not yet started).\",\"required\":true},{\"key\":\"willing\",\"label\":\"Willing to work as a student assistant\",\"result\":\"pass\",\"detail\":\"Your answer: Yes.\",\"required\":true},{\"key\":\"need\",\"label\":\"Shows financial need (family income)\",\"result\":\"confirm\",\"detail\":\"The unit decides what counts as financial need. Bring proof of family income.\",\"required\":true}]','You may qualify for the Student Assistant program since you are willing to work and your family income is within a modest bracket. Confirm the exact financial requirements with the DNSC unit.','gemini','2026-11-19 04:37:28','2026-11-19 04:37:18','2026-11-19 04:37:28'),
(430,11,5,'possible','possible','possible','high','{\"strengths\":[\"Filipino citizen\",\"First undergraduate degree\",\"No conflicting scholarship\"],\"concerns\":[\"Certificate of Indigency needed\",\"Call must be open\"],\"reminders\":[\"Secure Barangay Certificate of Indigency\",\"Check for open TDP call at DNSC\"]}',88,'[{\"key\":\"citizen\",\"label\":\"Filipino citizen\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"first_degree\",\"label\":\"Taking a first undergraduate degree (no previous bachelor\'s degree)\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"enrolled\",\"label\":\"Enrolled at DNSC (the call opens after the enrollment period)\",\"result\":\"pass\",\"detail\":\"Your answer: Incoming first-year (not yet started).\",\"required\":true},{\"key\":\"mrr\",\"label\":\"Within the Maximum Residency Rule (the normal length of the program plus one year)\",\"result\":\"na\",\"detail\":\"\",\"required\":true},{\"key\":\"no_other\",\"label\":\"Not receiving another national government-funded financial assistance (Free Higher Education and one-time grants such as AICS or SMART do not count, but TDP and SMART cannot be received in the same semester)\",\"result\":\"pass\",\"detail\":\"You do not receive a conflicting scholarship.\",\"required\":true},{\"key\":\"indigency\",\"label\":\"Can get a Certificate of Indigency from your barangay\",\"result\":\"confirm\",\"detail\":\"Ask the Punong Barangay where you live. If it cannot be secured, a Certificate of Tax Exemption or a Social Case Study from a registered social worker is accepted.\",\"required\":true},{\"key\":\"retention\",\"label\":\"Meets DNSC admission and retention policies\",\"result\":\"confirm\",\"detail\":\"DNSC and the CHED Regional Office check this when they validate your enrollment.\",\"required\":false},{\"key\":\"slots\",\"label\":\"A TDP call is open at DNSC this semester\",\"result\":\"confirm\",\"detail\":\"The UniFAST Secretariat issues the call after the enrollment period. Ask the DNSC Scholarship and Grants Unit.\",\"required\":false}]','You look like a match for the CHED Tulong Dunong Program as you meet the basic citizenship and enrollment criteria. You will need to secure a Certificate of Indigency to show financial need.','gemini','2026-11-19 04:37:28','2026-11-19 04:37:18','2026-11-19 04:37:28'),
(431,11,6,'not_eligible','not_eligible','not_eligible','low','{\"strengths\":[\"Filipino citizen\",\"First undergraduate degree\"],\"concerns\":[\"Not in Listahanan, 4Ps, solo parent, or IP group\"],\"reminders\":[]}',48,'[{\"key\":\"citizen\",\"label\":\"Filipino citizen\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"enrolled\",\"label\":\"Enrolled at DNSC (non-students cannot apply)\",\"result\":\"pass\",\"detail\":\"Your answer: Incoming first-year (not yet started).\",\"required\":true},{\"key\":\"no_degree\",\"label\":\"No previous undergraduate degree (not in a second undergraduate program)\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"duration\",\"label\":\"Not overstaying in the program (within the normal years plus a 1-year grace)\",\"result\":\"na\",\"detail\":\"\",\"required\":true},{\"key\":\"no_other\",\"label\":\"Not already a TDP, CHED scholarship or other national government aid beneficiary (one-time grants such as AICS or SMART do not count)\",\"result\":\"pass\",\"detail\":\"You do not receive a conflicting scholarship.\",\"required\":true},{\"key\":\"priority\",\"label\":\"In a TES group: Listahanan or 4Ps household (first priority), dependent of a solo parent in the DSWD registry, or Indigenous Peoples household listed by NCIP\",\"result\":\"fail\",\"detail\":\"None of the qualifying options were selected.\",\"required\":true},{\"key\":\"admission\",\"label\":\"Meets DNSC admission and retention policies\",\"result\":\"confirm\",\"detail\":\"DNSC checks this when it validates your enrollment.\",\"required\":false}]','You are not eligible for the Tertiary Education Subsidy because new slots prioritize specific marginalized groups such as 4Ps or Listahanan households, which do not apply to your profile.','gemini','2026-11-19 04:37:28','2026-11-19 04:37:18','2026-11-19 04:37:28'),
(432,11,7,'not_eligible','not_eligible','not_eligible','low','{\"strengths\":[\"Filipino citizen\",\"Incoming first-year student\"],\"concerns\":[\"Program not on priority S&T list\",\"Did not take DOST examination\"],\"reminders\":[]}',38,'[{\"key\":\"citizen\",\"label\":\"Natural-born Filipino citizen\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"incoming\",\"label\":\"Graduating from Grade 12, or a Grade 12 graduate not yet enrolled in college\",\"result\":\"pass\",\"detail\":\"Your answer: Incoming first-year (not yet started).\",\"required\":true},{\"key\":\"strand\",\"label\":\"STEM strand graduate, or in the top 5% of a non-STEM graduating class\",\"result\":\"confirm\",\"detail\":\"Your answer: HUMSS. This may qualify. Confirm with the provider.\",\"required\":true},{\"key\":\"course\",\"label\":\"Enrolling in a DOST-SEI priority S&T program\",\"result\":\"fail\",\"detail\":\"Your program (Bachelor of Public Administration) is not on the provider\'s list.\",\"required\":true},{\"key\":\"no_units\",\"label\":\"Has not earned any post-secondary (college or vocational) units\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"exam\",\"label\":\"DOST-SEI Scholarship Examination taken or passed (selection is by this exam)\",\"result\":\"fail\",\"detail\":\"Your answer: I have not taken it.\",\"required\":false},{\"key\":\"ra7687\",\"label\":\"RA 7687 track only: family income within DOST\'s set values, and living in your municipality for at least 4 years\",\"result\":\"confirm\",\"detail\":\"The Merit track has no income or residency requirement. For RA 7687, DOST-SEI checks your proof of income and your barangay\'s certificate of residency.\",\"required\":false}]','You are not eligible for the DOST-SEI scholarship because your program, Bachelor of Public Administration, is not a priority S&T course, and you have not taken the required exam.','gemini','2026-11-19 04:37:28','2026-11-19 04:37:18','2026-11-19 04:37:28'),
(433,11,8,'not_eligible','not_eligible','not_eligible','low','{\"strengths\":[\"First undergraduate degree\",\"Income within limit\"],\"concerns\":[\"Grade 12 GWA below 93%\"],\"reminders\":[]}',56,'[{\"key\":\"citizen\",\"label\":\"Filipino citizen\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"first_year\",\"label\":\"Incoming or current first-year college student\",\"result\":\"pass\",\"detail\":\"Your answer: 1st year.\",\"required\":true},{\"key\":\"gwa\",\"label\":\"Grade 12 GWA of at least 93%\",\"result\":\"fail\",\"detail\":\"You entered 90.5%, below the minimum of 93%.\",\"required\":true},{\"key\":\"income\",\"label\":\"Combined parent \\/ guardian gross income of \\u20b1500,000 or less\",\"result\":\"pass\",\"detail\":\"Your income range (Up to \\u20b1300,000) is within the limit.\",\"required\":true},{\"key\":\"no_other\",\"label\":\"Not already getting another national government-funded scholarship or grant, including TES or TDP (one-time grants do not count)\",\"result\":\"pass\",\"detail\":\"You do not receive a conflicting scholarship.\",\"required\":true},{\"key\":\"no_degree\",\"label\":\"Has not finished an undergraduate degree (no second-course takers)\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"no_credited_units\",\"label\":\"Not a transferee or shiftee with credited college units\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"ph_shs\",\"label\":\"Graduated from a senior high school in the Philippines\",\"result\":\"pass\",\"detail\":\"Your answer: Yes, in the Philippines.\",\"required\":true},{\"key\":\"priority\",\"label\":\"Enrolled in a CHED priority program with CHED recognition (non-priority programs cannot apply)\",\"result\":\"confirm\",\"detail\":\"Your program is not named in CHED\'s national priority list that BAKR uses (CMO No. 7, s. 2023). CHED may have newer or regional priorities and CHEDRO XI decides, so ask CHEDRO XI or the DNSC Scholarship and Grants Unit.\",\"required\":true}]','You are not eligible for the CHED Merit Scholarship because your Grade 12 GWA of 90.5% is below the strict 93% requirement set by the program.','gemini','2026-11-19 04:37:28','2026-11-19 04:37:18','2026-11-19 04:37:28'),
(434,11,9,'not_eligible','not_eligible','not_eligible','low','{\"strengths\":[\"Filipino citizen\",\"Income within limit\"],\"concerns\":[\"GWA below 95% and not in Top 5\"],\"reminders\":[]}',51,'[{\"key\":\"citizen\",\"label\":\"Filipino citizen (foreign or dual citizens cannot apply)\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"first_year\",\"label\":\"Incoming first-year college student (not repeating or re-entering first year)\",\"result\":\"pass\",\"detail\":\"Your answer: Incoming first-year (not yet started).\",\"required\":true},{\"key\":\"merit\",\"label\":\"Top 5 of the graduating class, or a Grade 12 GWA of at least 95%\",\"result\":\"fail\",\"detail\":\"Top 5 of the graduating class: no. Grade 12 GWA of at least 95%: no.\",\"required\":true},{\"key\":\"no_units\",\"label\":\"No college units earned before (including transferees or shiftees with credited units)\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"no_degree\",\"label\":\"Has not completed an undergraduate degree\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"income\",\"label\":\"Combined parent \\/ guardian gross income of \\u20b12,000,000 or less\",\"result\":\"pass\",\"detail\":\"Your income range (Up to \\u20b1300,000) is within the limit.\",\"required\":true},{\"key\":\"no_other\",\"label\":\"Not already getting a national government-funded scholarship or grant (private, LGU and one-time local grants do not count)\",\"result\":\"pass\",\"detail\":\"You do not receive a conflicting scholarship.\",\"required\":true},{\"key\":\"no_discipline\",\"label\":\"No pending case or record of disciplinary action in school\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"program\",\"label\":\"Enrolling in a CHED priority program\",\"result\":\"confirm\",\"detail\":\"Your program is not named in CHED\'s national priority list that BAKR uses (CMO No. 7, s. 2023). CHED may have newer or regional priorities and CHEDRO XI decides, so ask CHEDRO XI or the DNSC Scholarship and Grants Unit.\",\"required\":true},{\"key\":\"equity\",\"label\":\"Special equity group (10 extra ranking points): Indigenous Peoples, PWD, solo parent or dependent, living in poverty, or first-generation student\",\"result\":\"fail\",\"detail\":\"None of the qualifying options were selected.\",\"required\":false}]','You are not eligible for the Bagong Pilipinas Merit Scholarship because it requires a GWA of at least 95% or a Top 5 class ranking, while your GWA is 90.5%.','gemini','2026-11-19 04:37:28','2026-11-19 04:37:18','2026-11-19 04:37:28'),
(435,11,10,'possible','possible','possible','medium','{\"strengths\":[\"Grade 12 average above 90%\",\"No disciplinary sanction\"],\"concerns\":[\"Program eligibility for Public Administration\"],\"reminders\":[\"Confirm if Public Administration qualifies\",\"Prepare Grade 12 report card\"]}',77,'[{\"key\":\"citizen\",\"label\":\"Filipino citizen\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"first_year\",\"label\":\"Incoming first-year college student\",\"result\":\"pass\",\"detail\":\"Your answer: 1st year.\",\"required\":true},{\"key\":\"gwa\",\"label\":\"Grade 12 grade of at least 90%\",\"result\":\"pass\",\"detail\":\"You entered 90.5%. The minimum is 90%.\",\"required\":true},{\"key\":\"none_other\",\"label\":\"No other scholarship or educational assistance\",\"result\":\"pass\",\"detail\":\"You do not receive a conflicting scholarship.\",\"required\":true},{\"key\":\"course\",\"label\":\"A 3- to 4-year Business, STEM (not medical) or Sustainability program\",\"result\":\"confirm\",\"detail\":\"Your program (Bachelor of Public Administration) is on the list only for some specializations. Confirm with the provider.\",\"required\":true},{\"key\":\"conduct\",\"label\":\"No disciplinary sanction in senior high school\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true}]','You may qualify for the GrabScholar program since your GWA meets the 90% threshold. Check directly with the provider if your Bachelor of Public Administration program is accepted.','gemini','2026-11-19 04:37:28','2026-11-19 04:37:18','2026-11-19 04:37:28'),
(436,11,11,'not_eligible','not_eligible','not_eligible','low','{\"strengths\":[\"Income within limit\",\"GWA meets minimum\"],\"concerns\":[\"Not a Cebuana Lhuillier client\",\"Course not on approved list\"],\"reminders\":[]}',47,'[{\"key\":\"citizen\",\"label\":\"Filipino citizen\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"client\",\"label\":\"Cebuana Lhuillier client with a 24K Loyalty Card\",\"result\":\"fail\",\"detail\":\"Your answer: No. It is not on the provider\'s list.\",\"required\":true},{\"key\":\"savings\",\"label\":\"Cebuana Lhuillier Microsavings account (on the foundation\'s earlier qualifications page; not in the current FAQ)\",\"result\":\"fail\",\"detail\":\"Your answer: No. It is not on the provider\'s list.\",\"required\":false},{\"key\":\"enrolled\",\"label\":\"Enrolled, or enrolling, in a public state university or college (DNSC is a state college); any year level\",\"result\":\"pass\",\"detail\":\"Your answer: Incoming first-year (not yet started).\",\"required\":true},{\"key\":\"course\",\"label\":\"Supported course (Accountancy \\/ Finance, Business, Hospitality, Electrical \\/ Civil \\/ Mechanical \\/ Industrial Engineering, Architecture, Psychology, IT); no other courses are accepted\",\"result\":\"fail\",\"detail\":\"Your program (Bachelor of Public Administration) is not on the provider\'s list.\",\"required\":true},{\"key\":\"income\",\"label\":\"Total annual family income of \\u20b1350,000 or less\",\"result\":\"pass\",\"detail\":\"Your income range (Up to \\u20b1300,000) is within the limit.\",\"required\":true},{\"key\":\"gwa\",\"label\":\"GWA of at least 85% from the last semester or school (freshmen: senior high school grades)\",\"result\":\"pass\",\"detail\":\"You entered 90.5%. The minimum is 85%.\",\"required\":true},{\"key\":\"no_fail\",\"label\":\"No failing mark in any subject\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true}]','You are not eligible for this scholarship because it requires a Cebuana Lhuillier 24K card and an approved course in business, engineering, or IT, which excludes Public Administration.','gemini','2026-11-19 04:37:28','2026-11-19 04:37:18','2026-11-19 04:37:28'),
(437,11,12,'not_eligible','not_eligible','not_eligible','low','{\"strengths\":[\"Income within limit\",\"Incoming first-year student\"],\"concerns\":[\"Program not eligible\",\"Not child of ARB or farmer\\/fisher\"],\"reminders\":[]}',40,'[{\"key\":\"course\",\"label\":\"Enrolled in an eligible course: BS Fisheries and Aquatic Sciences, BS Food Technology, BS Agroforestry or BS Information Technology\",\"result\":\"fail\",\"detail\":\"Your program (Bachelor of Public Administration) is not on the provider\'s list.\",\"required\":true},{\"key\":\"year\",\"label\":\"Incoming first-year student (regular application), or a third- or fourth-year regular student (special application)\",\"result\":\"pass\",\"detail\":\"Incoming first-year student: yes.\",\"required\":true},{\"key\":\"family\",\"label\":\"Child or grandchild of an Agrarian Reform Beneficiary (ARB) or a small farmer \\/ fisher registered in the RSBSA\",\"result\":\"fail\",\"detail\":\"None of the qualifying options were selected.\",\"required\":true},{\"key\":\"income\",\"label\":\"Total annual family income of \\u20b1300,000 or less\",\"result\":\"pass\",\"detail\":\"Your income range (Up to \\u20b1300,000) is within the limit.\",\"required\":true},{\"key\":\"none_other\",\"label\":\"Not receiving any other financial assistance, grant or scholarship\",\"result\":\"pass\",\"detail\":\"You do not receive a conflicting scholarship.\",\"required\":true},{\"key\":\"no_fail\",\"label\":\"No conditional or failing grades\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"resident\",\"label\":\"Resident of Davao del Norte\",\"result\":\"fail\",\"detail\":\"OK.\",\"required\":true},{\"key\":\"standing\",\"label\":\"Special application: a regular student in good academic standing\",\"result\":\"na\",\"detail\":\"\",\"required\":false}]','You are not eligible for the LANDBANK scholarship because your program is not among the four required agriculture and IT courses, and you are not a child of an agrarian reform beneficiary.','gemini','2026-11-19 04:37:28','2026-11-19 04:37:18','2026-11-19 04:37:28'),
(438,11,13,'not_eligible','not_eligible','not_eligible','low','{\"strengths\":[\"Income within limit\",\"Incoming first-year student\"],\"concerns\":[\"Not a registered coconut farmer or dependent\"],\"reminders\":[]}',44,'[{\"key\":\"citizen\",\"label\":\"Filipino citizen\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"coconut\",\"label\":\"A registered coconut farmer in the NCFRS, or his \\/ her dependent\",\"result\":\"fail\",\"detail\":\"None of the qualifying options were selected.\",\"required\":true},{\"key\":\"income\",\"label\":\"Combined annual income of parents of \\u20b1300,000 or less\",\"result\":\"pass\",\"detail\":\"Your income range (Up to \\u20b1300,000) is within the limit.\",\"required\":true},{\"key\":\"status\",\"label\":\"Senior high school graduate, ALS graduate, or college student\",\"result\":\"pass\",\"detail\":\"Your answer: Incoming first-year (not yet started).\",\"required\":true},{\"key\":\"gwa\",\"label\":\"College students: GWA of at least 80%\",\"result\":\"na\",\"detail\":\"\",\"required\":true},{\"key\":\"no_other\",\"label\":\"Not enjoying any national government-funded scholarship program\",\"result\":\"pass\",\"detail\":\"You do not receive a conflicting scholarship.\",\"required\":true},{\"key\":\"priority\",\"label\":\"Enrolled in a CoScho priority program (80% of slots; 20% are for other fields)\",\"result\":\"fail\",\"detail\":\"Your program (Bachelor of Public Administration) is not on the provider\'s list.\",\"required\":false}]','You are not eligible for the Coconut Farmers Scholarship because it strictly requires applicants to be registered coconut farmers or their direct dependents.','gemini','2026-11-19 04:37:28','2026-11-19 04:37:18','2026-11-19 04:37:28'),
(439,11,14,'not_eligible','not_eligible','not_eligible','low','{\"strengths\":[\"GWA above minimum\",\"Incoming first-year student\"],\"concerns\":[\"Program not in Fisheries\"],\"reminders\":[]}',57,'[{\"key\":\"citizen\",\"label\":\"Natural-born Filipino citizen\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"incoming\",\"label\":\"Senior high school graduate or graduating student, not yet in college\",\"result\":\"pass\",\"detail\":\"Your answer: Incoming first-year (not yet started).\",\"required\":true},{\"key\":\"no_units\",\"label\":\"Has not earned any units in college\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"gwa\",\"label\":\"Senior high school GWA (last 3 semesters) of at least 80%\",\"result\":\"pass\",\"detail\":\"You entered 90.5%. The minimum is 80%.\",\"required\":true},{\"key\":\"component\",\"label\":\"Fits a component: child of a registered municipal fisherfolk (FCEG), member of an Indigenous Cultural Community \\/ Indigenous Peoples group (ICCs\\/IPs), or graduating with honors (FILG)\",\"result\":\"pass\",\"detail\":\"Graduating with honors (DepEd: GWA of 90 or higher): yes.\",\"required\":true},{\"key\":\"course\",\"label\":\"Taking a Bachelor of Science in Fisheries\",\"result\":\"fail\",\"detail\":\"Your program (Bachelor of Public Administration) is not on the provider\'s list.\",\"required\":true},{\"key\":\"conduct\",\"label\":\"Of good moral character, certified by the school head or principal\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"age\",\"label\":\"Not more than 25 years old at the time of the examination\",\"result\":\"pass\",\"detail\":\"Your answer is within the limit.\",\"required\":true},{\"key\":\"residence\",\"label\":\"You or your parent \\/ guardian have lived for at least 6 months in a municipality of the region where the slot is allotted\",\"result\":\"confirm\",\"detail\":\"Shown by the Barangay Residence Certificate. Ask BFAR XI which municipalities have slots.\",\"required\":true}]','You are not eligible for the BFAR Fisheries Scholarship because your chosen program is Public Administration rather than a Bachelor of Science in Fisheries.','gemini','2026-11-19 04:37:28','2026-11-19 04:37:18','2026-11-19 04:37:28'),
