(458,13,5,'possible','possible','possible','high','{\"strengths\":[\"Filipino citizen and first undergraduate degree\",\"Currently enrolled at DNSC\"],\"concerns\":[\"Certificate of Indigency required\"],\"reminders\":[\"Secure a Certificate of Indigency from your Punong Barangay\",\"Inquire with DNSC if the TDP call is currently open\"]}',89,'[{\"key\":\"citizen\",\"label\":\"Filipino citizen\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"first_degree\",\"label\":\"Taking a first undergraduate degree (no previous bachelor\'s degree)\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"enrolled\",\"label\":\"Enrolled at DNSC (the call opens after the enrollment period)\",\"result\":\"pass\",\"detail\":\"Your answer: Currently enrolled.\",\"required\":true},{\"key\":\"mrr\",\"label\":\"Within the Maximum Residency Rule (the normal length of the program plus one year)\",\"result\":\"pass\",\"detail\":\"Your answer: Yes.\",\"required\":true},{\"key\":\"no_other\",\"label\":\"Not receiving another national government-funded financial assistance (Free Higher Education and one-time grants such as AICS or SMART do not count, but TDP and SMART cannot be received in the same semester)\",\"result\":\"pass\",\"detail\":\"You do not receive a conflicting scholarship.\",\"required\":true},{\"key\":\"indigency\",\"label\":\"Can get a Certificate of Indigency from your barangay\",\"result\":\"confirm\",\"detail\":\"Ask the Punong Barangay where you live. If it cannot be secured, a Certificate of Tax Exemption or a Social Case Study from a registered social worker is accepted.\",\"required\":true},{\"key\":\"retention\",\"label\":\"Meets DNSC admission and retention policies\",\"result\":\"confirm\",\"detail\":\"DNSC and the CHED Regional Office check this when they validate your enrollment.\",\"required\":false},{\"key\":\"slots\",\"label\":\"A TDP call is open at DNSC this semester\",\"result\":\"confirm\",\"detail\":\"The UniFAST Secretariat issues the call after the enrollment period. Ask the DNSC Scholarship and Grants Unit.\",\"required\":false}]','You look like a strong match for the Tulong Dunong Program since you are a Filipino citizen pursuing your first degree at DNSC. You will need to obtain a Certificate of Indigency from your barangay and confirm when the application call opens.','gemini','2026-11-19 07:01:45','2026-11-19 07:01:28','2026-11-19 07:01:45'),
(459,13,6,'eligible','eligible','eligible','high','{\"strengths\":[\"4Ps household member\",\"Enrolled in first undergraduate degree\",\"Filipino citizen\"],\"concerns\":[],\"reminders\":[\"Prepare your Certificate of Registration and school ID\",\"Check enrollment validation schedules with DNSC\"]}',98,'[{\"key\":\"citizen\",\"label\":\"Filipino citizen\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"enrolled\",\"label\":\"Enrolled at DNSC (non-students cannot apply)\",\"result\":\"pass\",\"detail\":\"Your answer: Currently enrolled.\",\"required\":true},{\"key\":\"no_degree\",\"label\":\"No previous undergraduate degree (not in a second undergraduate program)\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"duration\",\"label\":\"Not overstaying in the program (within the normal years plus a 1-year grace)\",\"result\":\"pass\",\"detail\":\"Your answer: Yes.\",\"required\":true},{\"key\":\"no_other\",\"label\":\"Not already a TDP, CHED scholarship or other national government aid beneficiary (one-time grants such as AICS or SMART do not count)\",\"result\":\"pass\",\"detail\":\"You do not receive a conflicting scholarship.\",\"required\":true},{\"key\":\"priority\",\"label\":\"In a TES group: Listahanan or 4Ps household (first priority), dependent of a solo parent in the DSWD registry, or Indigenous Peoples household listed by NCIP\",\"result\":\"pass\",\"detail\":\"You selected: My household is a Pantawid Pamilyang Pilipino Program (4Ps) member.\",\"required\":true},{\"key\":\"admission\",\"label\":\"Meets DNSC admission and retention policies\",\"result\":\"confirm\",\"detail\":\"DNSC checks this when it validates your enrollment.\",\"required\":false}]','You are eligible for the Tertiary Education Subsidy because your household is a 4Ps member and you meet all the basic enrollment criteria. Make sure your enrollment is validated by DNSC so your details are included in the processing.','gemini','2026-11-19 07:01:45','2026-11-19 07:01:28','2026-11-19 07:01:45'),
(460,13,7,'not_eligible','not_eligible','not_eligible','low','{\"strengths\":[\"Enrolled in a priority S&T program\",\"No prior college units\"],\"concerns\":[\"Already enrolled in college (not a graduating Grade 12 student)\"],\"reminders\":[]}',50,'[{\"key\":\"citizen\",\"label\":\"Natural-born Filipino citizen\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"incoming\",\"label\":\"Graduating from Grade 12, or a Grade 12 graduate not yet enrolled in college\",\"result\":\"fail\",\"detail\":\"Your answer: Currently enrolled.\",\"required\":true},{\"key\":\"strand\",\"label\":\"STEM strand graduate, or in the top 5% of a non-STEM graduating class\",\"result\":\"unknown\",\"detail\":\"Answer this in your application so BAKR can check it.\",\"required\":true},{\"key\":\"course\",\"label\":\"Enrolling in a DOST-SEI priority S&T program\",\"result\":\"pass\",\"detail\":\"Your program (Bachelor of Science in Information Technology) is on the provider\'s list.\",\"required\":true},{\"key\":\"no_units\",\"label\":\"Has not earned any post-secondary (college or vocational) units\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"exam\",\"label\":\"DOST-SEI Scholarship Examination taken or passed (selection is by this exam)\",\"result\":\"unknown\",\"detail\":\"Answer this in your application so BAKR can check it.\",\"required\":false},{\"key\":\"ra7687\",\"label\":\"RA 7687 track only: family income within DOST\'s set values, and living in your municipality for at least 4 years\",\"result\":\"confirm\",\"detail\":\"The Merit track has no income or residency requirement. For RA 7687, DOST-SEI checks your proof of income and your barangay\'s certificate of residency.\",\"required\":false}]','The DOST-SEI Undergraduate Scholarship is designed for graduating high school students or those not yet enrolled in college. Since you are already in your second year of college, you do not meet this requirement.','gemini','2026-11-19 07:01:45','2026-11-19 07:01:28','2026-11-19 07:01:45'),
(461,13,8,'not_eligible','not_eligible','not_eligible','low','{\"strengths\":[\"Enrolled in an IT program\",\"Family income within the limit\"],\"concerns\":[\"Currently in 2nd year instead of incoming first-year\"],\"reminders\":[]}',57,'[{\"key\":\"citizen\",\"label\":\"Filipino citizen\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"first_year\",\"label\":\"Incoming or current first-year college student\",\"result\":\"fail\",\"detail\":\"Your answer: 2nd year.\",\"required\":true},{\"key\":\"gwa\",\"label\":\"Grade 12 GWA of at least 93%\",\"result\":\"unknown\",\"detail\":\"Answer this in your application so BAKR can check it.\",\"required\":true},{\"key\":\"income\",\"label\":\"Combined parent \\/ guardian gross income of \\u20b1500,000 or less\",\"result\":\"pass\",\"detail\":\"Your income range (Up to \\u20b1300,000) is within the limit.\",\"required\":true},{\"key\":\"no_other\",\"label\":\"Not already getting another national government-funded scholarship or grant, including TES or TDP (one-time grants do not count)\",\"result\":\"pass\",\"detail\":\"You do not receive a conflicting scholarship.\",\"required\":true},{\"key\":\"no_degree\",\"label\":\"Has not finished an undergraduate degree (no second-course takers)\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"no_credited_units\",\"label\":\"Not a transferee or shiftee with credited college units\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"ph_shs\",\"label\":\"Graduated from a senior high school in the Philippines\",\"result\":\"unknown\",\"detail\":\"Answer this in your application so BAKR can check it.\",\"required\":true},{\"key\":\"priority\",\"label\":\"Enrolled in a CHED priority program with CHED recognition (non-priority programs cannot apply)\",\"result\":\"pass\",\"detail\":\"Your program (Bachelor of Science in Information Technology) is on the provider\'s list.\",\"required\":true}]','This CHED merit scholarship is strictly for incoming or current first-year college students. Because you are already a second-year student, you are not eligible to apply.','gemini','2026-11-19 07:01:45','2026-11-19 07:01:28','2026-11-19 07:01:45'),
(462,13,9,'not_eligible','not_eligible','not_eligible','low','{\"strengths\":[\"Family income within the limit\",\"4Ps special equity group member\"],\"concerns\":[\"Currently in 2nd year instead of incoming first-year\"],\"reminders\":[]}',56,'[{\"key\":\"citizen\",\"label\":\"Filipino citizen (foreign or dual citizens cannot apply)\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"first_year\",\"label\":\"Incoming first-year college student (not repeating or re-entering first year)\",\"result\":\"fail\",\"detail\":\"Your answer: Currently enrolled.\",\"required\":true},{\"key\":\"merit\",\"label\":\"Top 5 of the graduating class, or a Grade 12 GWA of at least 95%\",\"result\":\"unknown\",\"detail\":\"Top 5 of the graduating class: no answer yet. Grade 12 GWA of at least 95%: no answer yet.\",\"required\":true},{\"key\":\"no_units\",\"label\":\"No college units earned before (including transferees or shiftees with credited units)\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"no_degree\",\"label\":\"Has not completed an undergraduate degree\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"income\",\"label\":\"Combined parent \\/ guardian gross income of \\u20b12,000,000 or less\",\"result\":\"pass\",\"detail\":\"Your income range (Up to \\u20b1300,000) is within the limit.\",\"required\":true},{\"key\":\"no_other\",\"label\":\"Not already getting a national government-funded scholarship or grant (private, LGU and one-time local grants do not count)\",\"result\":\"pass\",\"detail\":\"You do not receive a conflicting scholarship.\",\"required\":true},{\"key\":\"no_discipline\",\"label\":\"No pending case or record of disciplinary action in school\",\"result\":\"unknown\",\"detail\":\"Answer this in your application so BAKR can check it.\",\"required\":true},{\"key\":\"program\",\"label\":\"Enrolling in a CHED priority program\",\"result\":\"pass\",\"detail\":\"Your program (Bachelor of Science in Information Technology) is on the provider\'s list.\",\"required\":true},{\"key\":\"equity\",\"label\":\"Special equity group (10 extra ranking points): Indigenous Peoples, PWD, solo parent or dependent, living in poverty, or first-generation student\",\"result\":\"pass\",\"detail\":\"You selected: My household is a Pantawid Pamilyang Pilipino Program (4Ps) member.\",\"required\":false}]','The Bagong Pilipinas Merit Scholarship Program is restricted to incoming first-year college students. As a second-year student, you do not meet the entry year requirement.','gemini','2026-11-19 07:01:45','2026-11-19 07:01:28','2026-11-19 07:01:45'),
(463,13,10,'not_eligible','not_eligible','not_eligible','low','{\"strengths\":[\"Enrolled in a STEM program\",\"Filipino citizen\"],\"concerns\":[\"Currently in 2nd year instead of incoming first-year\"],\"reminders\":[]}',50,'[{\"key\":\"citizen\",\"label\":\"Filipino citizen\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"first_year\",\"label\":\"Incoming first-year college student\",\"result\":\"fail\",\"detail\":\"Your answer: 2nd year.\",\"required\":true},{\"key\":\"gwa\",\"label\":\"Grade 12 grade of at least 90%\",\"result\":\"unknown\",\"detail\":\"Answer this in your application so BAKR can check it.\",\"required\":true},{\"key\":\"none_other\",\"label\":\"No other scholarship or educational assistance\",\"result\":\"pass\",\"detail\":\"You do not receive a conflicting scholarship.\",\"required\":true},{\"key\":\"course\",\"label\":\"A 3- to 4-year Business, STEM (not medical) or Sustainability program\",\"result\":\"pass\",\"detail\":\"Your program (Bachelor of Science in Information Technology) is on the provider\'s list.\",\"required\":true},{\"key\":\"conduct\",\"label\":\"No disciplinary sanction in senior high school\",\"result\":\"unknown\",\"detail\":\"Answer this in your application so BAKR can check it.\",\"required\":true}]','GrabScholar is open exclusively to incoming first-year college students. Since you are already in your second year, you unfortunately cannot apply for this program.','gemini','2026-11-19 07:01:45','2026-11-19 07:01:28','2026-11-19 07:01:45'),
(464,13,11,'not_eligible','not_eligible','not_eligible','medium','{\"strengths\":[\"Enrolled in a supported IT course\",\"Family income within limit\",\"Good GWA\"],\"concerns\":[\"Not a Cebuana Lhuillier client with a 24K card\"],\"reminders\":[]}',73,'[{\"key\":\"citizen\",\"label\":\"Filipino citizen\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"client\",\"label\":\"Cebuana Lhuillier client with a 24K Loyalty Card\",\"result\":\"fail\",\"detail\":\"Your answer: No. It is not on the provider\'s list.\",\"required\":true},{\"key\":\"savings\",\"label\":\"Cebuana Lhuillier Microsavings account (on the foundation\'s earlier qualifications page; not in the current FAQ)\",\"result\":\"fail\",\"detail\":\"Your answer: No. It is not on the provider\'s list.\",\"required\":false},{\"key\":\"enrolled\",\"label\":\"Enrolled, or enrolling, in a public state university or college (DNSC is a state college); any year level\",\"result\":\"pass\",\"detail\":\"Your answer: Currently enrolled.\",\"required\":true},{\"key\":\"course\",\"label\":\"Supported course (Accountancy \\/ Finance, Business, Hospitality, Electrical \\/ Civil \\/ Mechanical \\/ Industrial Engineering, Architecture, Psychology, IT); no other courses are accepted\",\"result\":\"pass\",\"detail\":\"Your program (Bachelor of Science in Information Technology) is on the provider\'s list.\",\"required\":true},{\"key\":\"income\",\"label\":\"Total annual family income of \\u20b1350,000 or less\",\"result\":\"pass\",\"detail\":\"Your income range (Up to \\u20b1300,000) is within the limit.\",\"required\":true},{\"key\":\"gwa\",\"label\":\"GWA of at least 85% from the last semester or school (freshmen: senior high school grades)\",\"result\":\"pass\",\"detail\":\"You entered 88.96% (estimated from your 1.0\\u20135.0 grade). The minimum is 85%.\",\"required\":true},{\"key\":\"no_fail\",\"label\":\"No failing mark in any subject\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true}]','Although your course, income, and grades match the foundation\'s standards, this scholarship requires you to be a Cebuana Lhuillier client with a 24K Loyalty Card. Since you do not have this account, you cannot proceed.','gemini','2026-11-19 07:01:45','2026-11-19 07:01:28','2026-11-19 07:01:45'),
(465,13,12,'not_eligible','not_eligible','not_eligible','low','{\"strengths\":[\"Enrolled in Information Technology\",\"Resident of Davao del Norte\",\"Family income within limit\"],\"concerns\":[\"Not an incoming first-year or 3rd\\/4th year student\",\"Not a child or grandchild of an ARB or small farmer\\/fisher registered in RSBSA\"],\"reminders\":[]}',50,'[{\"key\":\"course\",\"label\":\"Enrolled in an eligible course: BS Fisheries and Aquatic Sciences, BS Food Technology, BS Agroforestry or BS Information Technology\",\"result\":\"pass\",\"detail\":\"Your program (Bachelor of Science in Information Technology) is on the provider\'s list.\",\"required\":true},{\"key\":\"year\",\"label\":\"Incoming first-year student (regular application), or a third- or fourth-year regular student (special application)\",\"result\":\"fail\",\"detail\":\"Incoming first-year student: no. Third- or fourth-year student: no.\",\"required\":true},{\"key\":\"family\",\"label\":\"Child or grandchild of an Agrarian Reform Beneficiary (ARB) or a small farmer \\/ fisher registered in the RSBSA\",\"result\":\"fail\",\"detail\":\"None of the qualifying options were selected.\",\"required\":true},{\"key\":\"income\",\"label\":\"Total annual family income of \\u20b1300,000 or less\",\"result\":\"pass\",\"detail\":\"Your income range (Up to \\u20b1300,000) is within the limit.\",\"required\":true},{\"key\":\"none_other\",\"label\":\"Not receiving any other financial assistance, grant or scholarship\",\"result\":\"pass\",\"detail\":\"You do not receive a conflicting scholarship.\",\"required\":true},{\"key\":\"no_fail\",\"label\":\"No conditional or failing grades\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"resident\",\"label\":\"Resident of Davao del Norte\",\"result\":\"pass\",\"detail\":\"OK.\",\"required\":true},{\"key\":\"standing\",\"label\":\"Special application: a regular student in good academic standing\",\"result\":\"confirm\",\"detail\":\"Your certified grades and the College Dean\'s recommendation show this.\",\"required\":false}]','This scholarship requires you to be either an incoming freshman or a 3rd/4th year student, and a relative of an agrarian reform beneficiary or registered farmer/fisherfolk. As a 2nd-year student without that specific family registry, you are not eligible.','gemini','2026-11-19 07:01:45','2026-11-19 07:01:28','2026-11-19 07:01:45'),
(466,13,13,'eligible','eligible','eligible','high','{\"strengths\":[\"Parent is a registered coconut farmer in NCFRS\",\"Family income and college GWA meet requirements\",\"Enrolled in a priority program\"],\"concerns\":[],\"reminders\":[\"Secure your PCA certification confirming coconut farmer registration\",\"Prepare a certified true copy of your latest college grades\"]}',100,'[{\"key\":\"citizen\",\"label\":\"Filipino citizen\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"coconut\",\"label\":\"A registered coconut farmer in the NCFRS, or his \\/ her dependent\",\"result\":\"pass\",\"detail\":\"You selected: My parent or guardian is a coconut farmer registered in the NCFRS (Philippine Coconut Authority).\",\"required\":true},{\"key\":\"income\",\"label\":\"Combined annual income of parents of \\u20b1300,000 or less\",\"result\":\"pass\",\"detail\":\"Your income range (Up to \\u20b1300,000) is within the limit.\",\"required\":true},{\"key\":\"status\",\"label\":\"Senior high school graduate, ALS graduate, or college student\",\"result\":\"pass\",\"detail\":\"Your answer: Currently enrolled.\",\"required\":true},{\"key\":\"gwa\",\"label\":\"College students: GWA of at least 80%\",\"result\":\"pass\",\"detail\":\"You entered 88.96%. The minimum is 80%.\",\"required\":true},{\"key\":\"no_other\",\"label\":\"Not enjoying any national government-funded scholarship program\",\"result\":\"pass\",\"detail\":\"You do not receive a conflicting scholarship.\",\"required\":true},{\"key\":\"priority\",\"label\":\"Enrolled in a CoScho priority program (80% of slots; 20% are for other fields)\",\"result\":\"pass\",\"detail\":\"Your program (Bachelor of Science in Information Technology) is on the provider\'s list.\",\"required\":false}]','You are eligible for the Coconut Farmers and Their Families Scholarship because your parent is a registered coconut farmer in the NCFRS and your income and grades fit the criteria. Gather your academic records and PCA certification to apply.','gemini','2026-11-19 07:01:45','2026-11-19 07:01:28','2026-11-19 07:01:45'),
(467,13,14,'not_eligible','not_eligible','not_eligible','low','{\"strengths\":[\"Filipino citizen and no college units in fisheries\"],\"concerns\":[\"Currently in college (not a senior high school graduate)\",\"Enrolled in IT instead of Fisheries\"],\"reminders\":[]}',36,'[{\"key\":\"citizen\",\"label\":\"Natural-born Filipino citizen\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"incoming\",\"label\":\"Senior high school graduate or graduating student, not yet in college\",\"result\":\"fail\",\"detail\":\"Your answer: Currently enrolled.\",\"required\":true},{\"key\":\"no_units\",\"label\":\"Has not earned any units in college\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"gwa\",\"label\":\"Senior high school GWA (last 3 semesters) of at least 80%\",\"result\":\"unknown\",\"detail\":\"Answer this in your application so BAKR can check it.\",\"required\":true},{\"key\":\"component\",\"label\":\"Fits a component: child of a registered municipal fisherfolk (FCEG), member of an Indigenous Cultural Community \\/ Indigenous Peoples group (ICCs\\/IPs), or graduating with honors (FILG)\",\"result\":\"unknown\",\"detail\":\"Parent or guardian is a registered municipal fisherfolk (FishR): no. Member of an Indigenous Peoples group: no. Graduating with honors (DepEd: GWA of 90 or higher): no answer yet.\",\"required\":true},{\"key\":\"course\",\"label\":\"Taking a Bachelor of Science in Fisheries\",\"result\":\"fail\",\"detail\":\"Your program (Bachelor of Science in Information Technology) is not on the provider\'s list.\",\"required\":true},{\"key\":\"conduct\",\"label\":\"Of good moral character, certified by the school head or principal\",\"result\":\"unknown\",\"detail\":\"Answer this in your application so BAKR can check it.\",\"required\":true},{\"key\":\"age\",\"label\":\"Not more than 25 years old at the time of the examination\",\"result\":\"pass\",\"detail\":\"Your answer is within the limit.\",\"required\":true},{\"key\":\"residence\",\"label\":\"You or your parent \\/ guardian have lived for at least 6 months in a municipality of the region where the slot is allotted\",\"result\":\"confirm\",\"detail\":\"Shown by the Barangay Residence Certificate. Ask BFAR XI which municipalities have slots.\",\"required\":true}]','The BFAR Fisheries Scholarship is reserved for graduating senior high school students taking a Bachelor of Science in Fisheries. Since you are already in college studying Information Technology, you do not qualify.','gemini','2026-11-19 07:01:45','2026-11-19 07:01:28','2026-11-19 07:01:45'),
