(502,16,7,'possible','possible','possible','medium','{\"strengths\":[\"Filipino citizen\",\"Enrolled in a priority S&T program\",\"Incoming first-year student\"],\"concerns\":[\"TVL strand instead of STEM\",\"Have not taken the DOST-SEI exam\"],\"reminders\":[\"Check if your TVL strand qualifies for the Merit track\",\"Inquire about future exam schedules\"]}',68,'[{\"key\":\"citizen\",\"label\":\"Natural-born Filipino citizen\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"incoming\",\"label\":\"Graduating from Grade 12, or a Grade 12 graduate not yet enrolled in college\",\"result\":\"pass\",\"detail\":\"Your answer: Incoming first-year (not yet started).\",\"required\":true},{\"key\":\"strand\",\"label\":\"STEM strand graduate, or in the top 5% of a non-STEM graduating class\",\"result\":\"confirm\",\"detail\":\"Your answer: TVL. This may qualify. Confirm with the provider.\",\"required\":true},{\"key\":\"course\",\"label\":\"Enrolling in a DOST-SEI priority S&T program\",\"result\":\"pass\",\"detail\":\"Your program (Bachelor of Science in Information Technology) is on the provider\'s list.\",\"required\":true},{\"key\":\"no_units\",\"label\":\"Has not earned any post-secondary (college or vocational) units\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"exam\",\"label\":\"DOST-SEI Scholarship Examination taken or passed (selection is by this exam)\",\"result\":\"fail\",\"detail\":\"Your answer: I have not taken it.\",\"required\":false},{\"key\":\"ra7687\",\"label\":\"RA 7687 track only: family income within DOST\'s set values, and living in your municipality for at least 4 years\",\"result\":\"confirm\",\"detail\":\"The Merit track has no income or residency requirement. For RA 7687, DOST-SEI checks your proof of income and your barangay\'s certificate of residency.\",\"required\":false}]','Your BS Information Technology program is a priority, but your TVL strand and lack of t