(509,16,14,'not_eligible','not_eligible','not_eligible','low','{\"strengths\":[\"High senior high school GWA\",\"Graduated with honors\"],\"concerns\":[\"Program is not Bachelor of Science in Fisheries\"],\"reminders\":[]}',57,'[{\"key\":\"citizen\",\"label\":\"Natural-born Filipino citizen\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"incoming\",\"label\":\"Senior high school graduate or graduating student, not yet in college\",\"result\":\"pass\",\"detail\":\"Your answer: Incoming first-year (not yet started).\",\"required\":true},{\"key\":\"no_units\",\"label\":\"Has not earned any units in college\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"gwa\",\"label\":\"Senior high school GWA (last 3 semesters) of at least 80%\",\"result\":\"pass\",\"detail\":\"You entered 95.5%. The minimum is 80%.\",\"required\":true},{\"key\":\"component\",\"label\":\"Fits a component: child of a registered municipal fisherfolk (FCEG), member of an Indigenous Cultural Community \\/ Indigenous Peoples group (ICCs\\/IPs), or graduating with honors (FILG)\",\"result\":\"pass\",\"detail\":\"Graduating with honors (DepEd: GWA of 90 or higher): yes.\",\"required\":true},{\"key\":\"course\",\"label\":\"Taking a Bachelor of Science in Fisheries\",\"result\":\"fail\",\"detail\":\"Your program (Bachelor of Science in Information Technology) is not on the provider\'s list.\",\"required\":true},{\"key\":\"conduct\",\"label\":\"Of good moral character, certified by the school head or principal\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"age\",\"label\":\"Not more than 25 years old at the time of the examination\",\"result\":\"pass\",\"detail\":\"Your answer is within the limit.\",\"required\":true},{\"key\":\"residence\",\"label\":\"You or your parent \\/ guardian have lived for at least 6 months in a municipality of the region where the slot is allotted\",\"result\":\"c