(510,17,1,'possible','possible','possible','medium','{\"strengths\":[\"Incoming DNSC student\"],\"concerns\":[\"Unpublished academic GWA requirement\"],\"reminders\":[\"Check with DNSC Scholarship Unit\",\"Prepare latest grades\",\"Prepare School ID\"]}',69,'[{\"key\":\"dnsc\",\"label\":\"DNSC student (current or incoming)\",\"result\":\"pass\",\"detail\":\"Your BAKR account is for a DNSC student.\",\"required\":true},{\"key\":\"enrolled\",\"label\":\"Currently enrolled or enrolling\",\"result\":\"pass\",\"detail\":\"Your answer: Incoming first-year (not yet started).\",\"required\":true},{\"key\":\"gwa\",\"label\":\"Meets the academic (GWA) requirement\",\"result\":\"confirm\",\"detail\":\"Set by the DNSC Scholarship and Grants Unit. It is not published in the sources BAKR uses.\",\"required\":true}]','You may qualify for this internal scholarship based on your status as an incoming student. However, the exact grade cut-off is not published, so you need to confirm this with the grants unit.','gemini','2026-11-20 18:50:49','2026-11-20 18:50:39','2026-11-20 18:50:49'),
