(512,17,3,'not_eligible','not_eligible','not_eligible','low','{\"strengths\":[\"Incoming DNSC student\"],\"concerns\":[\"Not currently enrolled yet\",\"Not an officer or board member\"],\"reminders\":[\"Consider applying after taking leadership roles in college\"]}',25,'[{\"key\":\"dnsc\",\"label\":\"DNSC student (current or incoming)\",\"result\":\"pass\",\"detail\":\"Your BAKR account is for a DNSC student.\",\"required\":true},{\"key\":\"enrolled\",\"label\":\"Currently enrolled\",\"result\":\"fail\",\"detail\":\"Your answer: Incoming first-year (not yet started).\",\"required\":true},{\"key\":\"leader\",\"label\":\"Student Supreme Council officer or Student Publication Editorial Board member\",\"result\":\"fail\",\"detail\":\"None of the qualifying options were selected.\",\"required\":true}]','This grant is intended for current student leaders such as Student Supreme Council officers, which does not match your incoming freshman status.','gemini','2026-11-20 18:50:49','2026-11-20 18:50:39','2026-11-20 18:50:49'),
(513,17,4,'not_eligible','not_eligible','not_eligible','low','{\"strengths\":[\"Incoming DNSC student\",\"Qualifying family income\"],\"concerns\":[\"Not willing to work as a student assistant\"],\"reminders\":[\"Check other non-working grants\"]}',37,'[{\"key\":\"dnsc\",\"label\":\"DNSC student (current or incoming)\",\"result\":\"pass\",\"detail\":\"Your BAKR account is for a DNSC student.\",\"required\":true},{\"key\":\"enrolled\",\"label\":\"Currently enrolled or enrolling\",\"result\":\"pass\",\"detail\":\"Your answer: Incoming first-year (not yet started).\",\"required\":true},{\"key\":\"willing\",\"label\":\"Willing to work as a student assistant\",\"result\":\"fail\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"need\",\"label\":\"Shows financial need (family income)\",\"result\":\"confirm\",\"detail\":\"The unit decides what counts as financial need. Bring proof of family income.\",\"required\":true}]','This financial assistance requires you to be willing to work as a student assistant, but your application indicates you are not willing to take on this role.','gemini','2026-11-20 18:50:49','2026-11-20 18:50:39','2026-11-20 18:50:49'),
(514,17,5,'possible','possible','possible','high','{\"strengths\":[\"Filipino citizen\",\"First undergraduate degree\",\"Incoming DNSC student\"],\"concerns\":[\"Unpublished barangay certificate requirement\",\"Open call required\"],\"reminders\":[\"Secure a Certificate of Indigency\",\"Ask DNSC about the active TDP call\"]}',88,'[{\"key\":\"citizen\",\"label\":\"Filipino citizen\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"first_degree\",\"label\":\"Taking a first undergraduate degree (no previous bachelor\'s degree)\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"enrolled\",\"label\":\"Enrolled at DNSC (the call opens after the enrollment period)\",\"result\":\"pass\",\"detail\":\"Your answer: Incoming first-year (not yet started).\",\"required\":true},{\"key\":\"mrr\",\"label\":\"Within the Maximum Residency Rule (the normal length of the program plus one year)\",\"result\":\"na\",\"detail\":\"\",\"required\":true},{\"key\":\"no_other\",\"label\":\"Not receiving another national government-funded financial assistance (Free Higher Education and one-time grants such as AICS or SMART do not count, but TDP and SMART cannot be received in the same semester)\",\"result\":\"pass\",\"detail\":\"You do not receive a conflicting scholarship.\",\"required\":true},{\"key\":\"indigency\",\"label\":\"Can get a Certificate of Indigency from your barangay\",\"result\":\"confirm\",\"detail\":\"Ask the Punong Barangay where you live. If it cannot be secured, a Certificate of Tax Exemption or a Social Case Study from a registered social worker is accepted.\",\"required\":true},{\"key\":\"retention\",\"label\":\"Meets DNSC admission and retention policies\",\"result\":\"confirm\",\"detail\":\"DNSC and the CHED Regional Office check this when they validate your enrollment.\",\"required\":false},{\"key\":\"slots\",\"label\":\"A TDP call is open at DNSC this semester\",\"result\":\"confirm\",\"deta