(572,21,7,'not_eligible','not_eligible','not_eligible','low','{\"strengths\":[\"Filipino citizen\",\"High school graduate\"],\"concerns\":[\"Program is not a priority S&T course\",\"Did not take the DOST exam\"],\"reminders\":[\"Explore non-STEM scholarships.\"]}',38,'[{\"key\":\"citizen\",\"label\":\"Natural-born Filipino citizen\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"incoming\",\"label\":\"Graduating from Grade 12, or a Grade 12 graduate not yet enrolled in college\",\"result\":\"pass\",\"detail\":\"Your answer: Incoming first-year (not yet started).\",\"required\":true},{\"key\":\"strand\",\"label\":\"STEM strand graduate, or in the top 5% of a non-STEM graduating class\",\"result\":\"confirm\",\"detail\":\"Your answer: TVL. This may qualify. Confirm with the provider.\",\"required\":true},{\"key\":\"course\",\"label\":\"Enrolling in a DOST-SEI priority S&T program\",\"result\":\"fail\",\"detail\":\"Your program (Bachelor of Science in Tourism Management) is not on the provider\'s list.\",\"required\":true},{\"key\":\"no_units\",\"label\":\"Has not earned any post-secondary (college or vocational) units\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"exam\",\"label\":\"DOST-SEI Scholarship Examination taken or passed (selection is by this exam)\",\"result\":\"fail\",\"detail\":\"Your answer: I have not taken it.\",\"required\":false},{\"key\":\"ra7687\",\"label\":\"RA 7687 track only: family income within DOST\'s set values, and living in your municipality for at least 4 years\",\"result\":\"confirm\",\"detail\":\"The Merit track has no income or residency requirement. For RA 7687, DOST-SEI checks your proof of income and your barangay\'s certificate of residency.\",\"required\":false}]','Your chosen program in Tourism Management is not among the priority science and technology courses required by DOST-SEI.','gemini','2026-11-21 03:53:11','2026-11-21 02:53:47','2026-11-21 03:53:11'),
(573,21,8,'eligible','eligible','eligible','high','{\"strengths\":[\"High school GWA of 95.9%\",\"Income below \\u20b1500k\",\"First undergraduate degree\"],\"concerns\":[],\"reminders\":[\"Prepare your PSA birth certificate and Form 138.\",\"Submit your application through CHEDRO.\"]}',100,'[{\"key\":\"citizen\",\"label\":\"Filipino citizen\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"first_year\",\"label\":\"Incoming or current first-year college student\",\"result\":\"pass\",\"detail\":\"Your answer: 1st year.\",\"required\":true},{\"key\":\"gwa\",\"label\":\"Grade 12 GWA of at least 93%\",\"result\":\"pass\",\"detail\":\"You entered 95.9%. The minimum is 93%.\",\"required\":true},{\"key\":\"income\",\"label\":\"Combined parent \\/ guardian gross income of \\u20b1500,000 or less\",\"result\":\"pass\",\"detail\":\"Your income range (Below \\u20b1300k) is within the limit.\",\"required\":true},{\"key\":\"no_other\",\"label\":\"Not already getting another national government-funded scholarship or grant, including TES or TDP (one-time grants do not count)\",\"result\":\"pass\",\"detail\":\"You do not receive a conflicting scholarship.\",\"required\":true},{\"key\":\"no_degree\",\"label\":\"Has not finished an undergraduate degree (no second-course takers)\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"no_credited_units\",\"label\":\"Not a transferee or shiftee with credited college units\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"ph_shs\",\"label\":\"Graduated from a senior high school in the Philippines\",\"result\":\"pass\",\"detail\":\"Your answer: Yes, in the Philippines.\",\"required\":true},{\"key\":\"priority\",\"label\":\"Enrolled in a CHED priority program with CHED recognition (non-priority programs cannot apply)\",\"result\":\"pass\",\"detail\":\"Your program (Bachelor of Science in Tourism Management) is on the provider\'s list.\",\"required\":true}]','You meet all the published requirements for this merit scholarship with your high grades and low family income, though slots are subject to ranking.','gemini','2026-11-21 03:53:11','2026-11-21 02:53:47','2026-11-21 03:53:11'),
(574,21,9,'eligible','eligible','eligible','high','{\"strengths\":[\"Top 5 graduating class standing\",\"GWA of 95.9%\",\"Low family income\"],\"concerns\":[],\"reminders\":[\"Fill out the BPMSP online portal application.\",\"Prepare your proof of income and Form 138.\"]}',96,'[{\"key\":\"citizen\",\"label\":\"Filipino citizen (foreign or dual citizens cannot apply)\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"first_year\",\"label\":\"Incoming first-year college student (not repeating or re-entering first year)\",\"result\":\"pass\",\"detail\":\"Your answer: Incoming first-year (not yet started).\",\"required\":true},{\"key\":\"merit\",\"label\":\"Top 5 of the graduating class, or a Grade 12 GWA of at least 95%\",\"result\":\"pass\",\"detail\":\"Top 5 of the graduating class: yes.\",\"required\":true},{\"key\":\"no_units\",\"label\":\"No college units earned before (including transferees or shiftees with credited units)\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"no_degree\",\"label\":\"Has not completed an undergraduate degree\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"income\",\"label\":\"Combined parent \\/ guardian gross income of \\u20b12,000,000 or less\",\"result\":\"pass\",\"detail\":\"Your income range (Below \\u20b1300k) is within the limit.\",\"required\":true},{\"key\":\"no_other\",\"label\":\"Not already getting a national government-funded scholarship or grant (private, LGU and one-time local grants do not count)\",\"result\":\"pass\",\"detail\":\"You do not receive a conflicting scholarship.\",\"required\":true},{\"key\":\"no_discipline\",\"label\":\"No pending case or record of disciplinary action in school\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"program\",\"label\":\"Enrolling in a CHED priority program\",\"result\":\"pass\",\"detail\":\"Your program (Bachelor of Science in Tourism Management) is on the provider\'s list.\",\"required\":true},{\"key\":\"equity\",\"label\":\"Special equity group (10 extra ranking points): Indigenous Peoples, PWD, solo parent or dependent, living in poverty, or first-generation student\",\"result\":\"fail\",\"detail\":\"None of the qualifying options were selected.\",\"required\":false}]','You are a great match for this merit program because you finished in the Top 5 of your class and meet the income threshold.','gemini','2026-11-21 03:53:11','2026-11-21 02:53:47','2026-11-21 03:53:11'),
(575,21,10,'possible','possible','possible','medium','{\"strengths\":[\"High school average above 90%\",\"Incoming freshman\"],\"concerns\":[\"Program alignment needs confirmation\"],\"reminders\":[\"Confirm if Tourism Management qualifies under their business or sustainability tracks.\",\"Prepare your Grade 12 report card.\"]}',77,'[{\"key\":\"citizen\",\"label\":\"Filipino citizen\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"first_year\",\"label\":\"Incoming first-year college student\",\"result\":\"pass\",\"detail\":\"Your answer: 1st year.\",\"required\":true},{\"key\":\"gwa\",\"label\":\"Grade 12 grade of at least 90%\",\"result\":\"pass\",\"detail\":\"You entered 95.9%. The minimum is 90%.\",\"required\":true},{\"key\":\"none_other\",\"label\":\"No other scholarship or educational assistance\",\"result\":\"pass\",\"detail\":\"You do not receive a conflicting scholarship.\",\"required\":true},{\"key\":\"course\",\"label\":\"A 3- to 4-year Business, STEM (not medical) or Sustainability program\",\"result\":\"confirm\",\"detail\":\"Your program (Bachelor of Science in Tourism Management) is on the list only for some specializations. Confirm with the provider.\",\"required\":true},{\"key\":\"conduct\",\"label\":\"No disciplinary sanction in senior high school\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true}]','Your academic standing easily meets the criteria, but you will need to check with Grab if your tourism program fits their accepted fields.','gemini','2026-11-21 03:53:11','2026-11-21 02:53:47','2026-11-21 03:53:11'),
(576,21,11,'possible','possible','possible','medium','{\"strengths\":[\"Cebuana Lhuillier client with account\",\"Family income below \\u20b1350k\",\"High school GWA of 95.9%\"],\"concerns\":[\"Course eligibility needs confirmation\"],\"reminders\":[\"Bring your 24K Loyalty Card.\",\"Confirm if Tourism Management is accepted under their hospitality or business tracks.\"]}',78,'[{\"key\":\"citizen\",\"label\":\"Filipino citizen\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"client\",\"label\":\"Cebuana Lhuillier client with a 24K Loyalty Card\",\"result\":\"pass\",\"detail\":\"Your answer: Yes, I am.\",\"required\":true},{\"key\":\"savings\",\"label\":\"Cebuana Lhuillier Microsavings account (on the foundation\'s earlier qualifications page; not in the current FAQ)\",\"result\":\"pass\",\"detail\":\"Your answer: Yes.\",\"required\":false},{\"key\":\"enrolled\",\"label\":\"Enrolled, or enrolling, in a public state university or college (DNSC is a state college); any year level\",\"result\":\"pass\",\"detail\":\"Your answer: Incoming first-year (not yet started).\",\"required\":true},{\"key\":\"course\",\"label\":\"Supported course (Accountancy \\/ Finance, Business, Hospitality, Electrical \\/ Civil \\/ Mechanical \\/ Industrial Engineering, Architecture, Psychology, IT); no other courses are accepted\",\"result\":\"confirm\",\"detail\":\"Your program (Bachelor of Science in Tourism Management) is on the list only for some specializations. Confirm with the provider.\",\"required\":true},{\"key\":\"income\",\"label\":\"Total annual family income of \\u20b1350,000 or less\",\"result\":\"pass\",\"detail\":\"Your income range (Below \\u20b1300k) is within the limit.\",\"required\":true},{\"key\":\"gwa\",\"label\":\"GWA of at least 85% from the last semester or school (freshmen: senior high school grades)\",\"result\":\"pass\",\"detail\":\"You entered 95.9%. The minimum is 85%.\",\"required\":true},{\"key\":\"no_fail\",\"label\":\"No failing mark in any subject\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true}]','You match the financial and client requirements nicely, but you should verify with the foundation if your tourism course is covered.','gemini','2026-11-21 03:53:11','2026-11-21 02:53:47','2026-11-21 03:53:11'),
(577,21,12,'not_eligible','not_eligible','not_eligible','low','{\"strengths\":[\"Family income within limits\",\"Resident of Davao del Norte\"],\"concerns\":[\"Program is not an eligible agriculture or IT course\",\"Not a child of an ARB or small farmer\"],\"reminders\":[\"Look for general institutional or merit grants.\"]}',40,'[{\"key\":\"course\",\"label\":\"Enrolled in an eligible course: BS Fisheries and Aquatic Sciences, BS Food Technology, BS Agroforestry or BS Information Technology\",\"result\":\"fail\",\"detail\":\"Your program (Bachelor of Science in Tourism Management) is not on the provider\'s list.\",\"required\":true},{\"key\":\"year\",\"label\":\"Incoming first-year student (regular application), or a third- or fourth-year regular student (special application)\",\"result\":\"pass\",\"detail\":\"Incoming first-year student: yes.\",\"required\":true},{\"key\":\"family\",\"label\":\"Child or grandchild of an Agrarian Reform Beneficiary (ARB) or a small farmer \\/ fisher registered in the RSBSA\",\"result\":\"fail\",\"detail\":\"None of the qualifying options were selected.\",\"required\":true},{\"key\":\"income\",\"label\":\"Total annual family income of \\u20b1300,000 or less\",\"result\":\"pass\",\"detail\":\"Your income range (Below \\u20b1300k) is within the limit.\",\"required\":true},{\"key\":\"none_other\",\"label\":\"Not receiving any other financial assistance, grant or scholarship\",\"result\":\"pass\",\"detail\":\"You do not receive a conflicting scholarship.\",\"required\":true},{\"key\":\"no_fail\",\"label\":\"No conditional or failing grades\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"resident\",\"label\":\"Resident of Davao del Norte\",\"result\":\"fail\",\"detail\":\"OK.\",\"required\":true},{\"key\":\"standing\",\"label\":\"Special application: a regular student in good academic standing\",\"result\":\"na\",\"detail\":\"\",\"required\":false}]','You are not eligible because this program requires specific agricultural or IT courses and farming sector lineage.','gemini','2026-11-21 03:53:11','2026-11-21 02:53:47','2026-11-21 03:53:11'),
(578,21,13,'not_eligible','not_eligible','not_eligible','low','{\"strengths\":[\"Low family income\",\"Incoming freshman\"],\"concerns\":[\"Not a registered coconut farmer or dependent\"],\"reminders\":[\"Check other CHED options.\"]}',48,'[{\"key\":\"citizen\",\"label\":\"Filipino citizen\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"coconut\",\"label\":\"A registered coconut farmer in the NCFRS, or his \\/ her dependent\",\"result\":\"fail\",\"detail\":\"None of the qualifying options were selected.\",\"required\":true},{\"key\":\"income\",\"label\":\"Combined annual income of parents of \\u20b1300,000 or less\",\"result\":\"pass\",\"detail\":\"Your income range (Below \\u20b1300k) is within the limit.\",\"required\":true},{\"key\":\"status\",\"label\":\"Senior high school graduate, ALS graduate, or college student\",\"result\":\"pass\",\"detail\":\"Your answer: Incoming first-year (not yet started).\",\"required\":true},{\"key\":\"gwa\",\"label\":\"College students: GWA of at least 80%\",\"result\":\"na\",\"detail\":\"\",\"required\":true},{\"key\":\"no_other\",\"label\":\"Not enjoying any national government-funded scholarship program\",\"result\":\"pass\",\"detail\":\"You do not receive a conflicting scholarship.\",\"required\":true},{\"key\":\"priority\",\"label\":\"Enrolled in a CoScho priority program (80% of slots; 20% are for other fields)\",\"result\":\"confirm\",\"detail\":\"Your program (Bachelor of Science in Tourism Management) is on the list only for some specializations. Confirm with the provider.\",\"required\":false}]','This coconut farmers scholarship requires you to be a registered coconut farmer or a direct dependent, which does not apply to you.','gemini','2026-11-21 03:53:11','2026-11-21 02:53:47','2026-11-21 03:53:11'),
(579,21,14,'not_eligible','not_eligible','not_eligible','low','{\"strengths\":[\"High GWA of 95.9%\",\"Honors standing\"],\"concerns\":[\"Program is not Bachelor of Science in Fisheries\"],\"reminders\":[\"Explore tourism-aligned scholarships instead.\"]}',57,'[{\"key\":\"citizen\",\"label\":\"Natural-born Filipino citizen\",\"result\":\"pass\",\"detail\":\"Your answer: Filipino citizen.\",\"required\":true},{\"key\":\"incoming\",\"label\":\"Senior high school graduate or graduating student, not yet in college\",\"result\":\"pass\",\"detail\":\"Your answer: Incoming first-year (not yet started).\",\"required\":true},{\"key\":\"no_units\",\"label\":\"Has not earned any units in college\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"gwa\",\"label\":\"Senior high school GWA (last 3 semesters) of at least 80%\",\"result\":\"pass\",\"detail\":\"You entered 95.9%. The minimum is 80%.\",\"required\":true},{\"key\":\"component\",\"label\":\"Fits a component: child of a registered municipal fisherfolk (FCEG), member of an Indigenous Cultural Community \\/ Indigenous Peoples group (ICCs\\/IPs), or graduating with honors (FILG)\",\"result\":\"pass\",\"detail\":\"Graduating with honors (DepEd: GWA of 90 or higher): yes.\",\"required\":true},{\"key\":\"course\",\"label\":\"Taking a Bachelor of Science in Fisheries\",\"result\":\"fail\",\"detail\":\"Your program (Bachelor of Science in Tourism Management) is not on the provider\'s list.\",\"required\":true},{\"key\":\"conduct\",\"label\":\"Of good moral character, certified by the school head or principal\",\"result\":\"pass\",\"detail\":\"Your answer: No.\",\"required\":true},{\"key\":\"age\",\"label\":\"Not more than 25 years old at the time of the examination\",\"result\":\"pass\",\"detail\":\"Your answer is within the limit.\",\"required\":true},{\"key\":\"residence\",\"label\":\"You or your parent \\/ guardian have lived for at least 6 months in a municipality of the region where the slot is allotted\",\"result\":\"confirm\",\"detail\":\"Shown by the Barangay Residence Certificate. Ask BFAR XI which municipalities have slots.\",\"required\":true}]','You have great grades, but this scholarship is exclusively for students taking a Bachelor of Science in Fisheries.','gemini','2026-11-21 03:53:11','2026-11-21 02:53:47','2026-11-21 03:53:11');
