INSERT INTO `scholarship_revisions` VALUES
(1,7,2,'{\"overview\":\"A DOST-SEI scholarship for talented Filipino students entering priority Science and Technology programs. Two tracks: the Merit Scholarship (formerly NSDB \\/ NSTA) for students with high aptitude in science and mathematics, and the RA 7687 Scholarship for students whose families\' socio-economic status does not exceed DOST\'s set values. Scholars may study at state colleges like DNSC.\",\"benefits\":[\"Tuition and other school fees: actual fees up to \\u20b140,000 a year (for scholars in private schools)\",\"Learning materials and \\/ or connectivity allowance: \\u20b110,000 a year\",\"Monthly living allowance: \\u20b18,000 a month\",\"Clothing allowance: \\u20b11,000 (first semester of first year only)\",\"Transportation: one economy-class round trip a year, if you study outside your home province\",\"Group accident and health insurance\",\"Thesis allowance: \\u20b110,000\",\"Research dissemination grant: up to \\u20b150,000 (applied for by the scholar, subject to approval)\",\"Graduation allowance: \\u20b11,000\",\"Mid-year term, if your curriculum requires it: fees up to \\u20b110,000, \\u20b12,000 learning materials, and \\u20b18,000 a month\"],\"documents\":[\"Form C \\u2013 Certificate of Good Moral Character\",\"Form D \\u2013 Certificate of Good Health\",\"Form E \\u2013 Principal\'s Certification: E1 Grade 12 STEM strand; E2 Grade 12 non-STEM strand in the upper 5% of the class; E3 homeschool; E4 Alternative Learning System\",\"Form F \\u2013 Certificate of Residency\",\"Form G \\u2013 Parent\'s Certification that you have no pending immigration application to another country\",\"Form H \\u2013 DOST-SEI Scholarship Examination \\/ Award\",\"Form I \\u2013 Applicant\'s Certification of No Post-Secondary Units\",\"Form J \\u2013 Signed Declaration of Applicant and Parent \\/ Legal Guardian\",\"Recent passport-size picture (4.5 cm \\u00d7 3.5 cm)\",\"Birth certificate\",\"One proof of income of your parents, guardian or spouse: 2024 Income Tax Return; BIR Form 1701; OFW employment contract; BIR Certificate of Exemption from Filing of ITR; Certificate of Indigency; Certificate of Employment with Compensation; or proof of pension\",\"Notarized Affidavit of Guardianship, if applicable\",\"Marriage certificate, if married\"],\"renewal_requirements\":[],\"application_route\":\"Apply online through the DOST-SEI scholarship site (science-scholarships.ph), where the forms are posted, then take the DOST-SEI Scholarship Examination. Qualifiers enroll in a priority S&T program at the University of the Philippines, a state college such as DNSC, or a private school that is a CHED Center of Excellence \\/ Development or has FAAP Level III accreditation.\",\"window_note\":\"For Grade 12 students graduating in SY 2025\\u20132026, and earlier Grade 12 graduates not yet enrolled in college. Watch science-scholarships.ph for the call and exam schedule.\",\"application_opens_on\":null,\"application_closes_on\":null,\"results_on\":null,\"official_url\":\"https:\\/\\/www.science-scholarships.ph\\/\",\"rules\":[{\"key\":\"citizen\",\"label\":\"Natural-born Filipino citizen\",\"type\":\"eq\",\"fact\":\"citizenship\",\"value\":\"filipino\",\"required\":true,\"weight\":2,\"src\":\"web\"},{\"key\":\"incoming\",\"label\":\"Graduating from Grade 12, or a Grade 12 graduate not yet enrolled in college\",\"type\":\"eq\",\"fact\":\"enrollment_status\",\"value\":\"incoming_first_year\",\"required\":true,\"weight\":3,\"src\":\"web\"},{\"key\":\"strand\",\"label\":\"STEM strand graduate, or in the top 5% of a non-STEM graduating class\",\"type\":\"confirm\",\"fact\":\"shs_gwa_percent\",\"required\":true,\"weight\":3,\"src\":\"web\",\"confirm_note\":\"Your principal certifies this on Form E (E1 for STEM, E2 for non-STEM top 5%; E3 homeschool; E4 ALS).\"},{\"key\":\"course\",\"label\":\"Enrolling in a DOST-SEI priority S&T program\",\"type\":\"program_in\",\"fact\":\"program_name\",\"required\":true,\"weight\":5,\"src\":\"web\",\"pass\":[\"Bachelor of Science in Agro-Forestry\",\"Bachelor of Science in Fisheries and Aquatic Sciences\",\"Bachelor of Science in Food Technology\",\"Bachelor of Science in Information Systems\",\"Bachelor of Science in Information Technology\",\"Bachelor of Science in Marine Biology\",\"Bachelor of Secondary Education - Mathematics\",\"Bachelor of Secondary Education - Science\"],\"maybe\":[\"Bachelor of Technology and Livelihood Education\"],\"not\":[\"Bachelor of Arts in Communication\",\"Bachelor of Physical Education\",\"Bachelor of Public Administration\",\"Bachelor of Science in Criminology\",\"Bachelor of Science in Disaster Resilience and Management\",\"Bachelor of Science in Entrepreneurship\",\"Bachelor of Science in Social Work\",\"Bachelor of Science in Tourism Management\",\"Bachelor of Secondary Education - English\"]},{\"key\":\"no_units\",\"label\":\"Has not earned any post-secondary (college or vocational) units\",\"type\":\"eq\",\"fact\":\"previous_units\",\"value\":\"no\",\"required\":true,\"weight\":2,\"src\":\"web\"},{\"key\":\"exam\",\"label\":\"DOST-SEI Scholarship Examination taken or passed (selection is by this exam)\",\"type\":\"in\",\"fact\":\"dost_exam\",\"value\":[\"taken_waiting\",\"passed\"],\"required\":false,\"weight\":3,\"src\":\"web\"},{\"key\":\"ra7687\",\"label\":\"RA 7687 track only: family income within DOST\'s set values, and living in your municipality for at least 4 years\",\"type\":\"confirm\",\"fact\":\"income_max\",\"required\":false,\"weight\":1,\"src\":\"web\",\"confirm_note\":\"The Merit track has no income or residency requirement. For RA 7687, DOST-SEI checks your proof of income and your barangay\'s certificate of residency.\"}]}','{\"overview\":\"A DOST-SEI scholarship for talented Filipino students entering priority Science and Technology programs. Two tracks: the Merit Scholarship (formerly NSDB \\/ NSTA) for students with high aptitude in science and mathematics, and the RA 7687 Scholarship for students whose families\' socio-economic status does not exceed DOST\'s set values. Scholars may study at state colleges like DNSC.\",\"benefits\":[\"Tuition and other school fees: actual fees up to \\u20b140,000 a year (for scholars in private schools)\",\"Learning materials and \\/ or connectivity allowance: \\u20b110,000 a year\",\"Monthly living allowance: \\u20b18,000 a month\",\"Clothing allowance: \\u20b11,000 (first semester of first year only)\",\"Transportation: one economy-class round trip a year, if you study outside your home province\",\"Group accident and health insurance\",\"Thesis allowance: \\u20b110,000\",\"Research dissemination grant: up to \\u20b150,000 (applied for by the scholar, subject to approval)\",\"Graduation allowance: \\u20b11,000\",\"Mid-year term, if your curriculum requires it: fees up to \\u20b110,000, \\u20b12,000 learning materials, and \\u20b18,000 a month\"],\"documents\":[\"Form C \\u2013 Certificate of Good Moral Character\",\"Form D \\u2013 Certificate of Good Health\",\"Form E \\u2013 Principal\'s Certification: E1 Grade 12 STEM strand; E2 Grade 12 non-STEM strand in the upper 5% of the class; E3 homeschool; E4 Alternative Learning System\",\"Form F \\u2013 Certificate of Residency\",\"Form G \\u2013 Parent\'s Certification that you have no pending immigration application to another country\",\"Form H \\u2013 DOST-SEI Scholarship Examination \\/ Award\",\"Form I \\u2013 Applicant\'s Certification of No Post-Secondary Units\",\"Form J \\u2013 Signed Declaration of Applicant and Parent \\/ Legal Guardian\",\"Recent passport-size picture (4.5 cm \\u00d7 3.5 cm)\",\"Birth certificate\",\"One proof of income of your parents, guardian or spouse: 2024 Income Tax Return; BIR Form 1701; OFW employment contract; BIR Certificate of Exemption from Filing of ITR; Certificate of Indigency; Certificate of Employment with Compensation; or proof of pension\",\"Notarized Affidavit of Guardianship, if applicable\",\"Marriage certificate, if married\"],\"renewal_requirements\":[{\"name\":\"Certificate of Registration\",\"note\":\"From the registrar\",\"types\":[\"pdf\",\"jpg\",\"png\"],\"max_mb\":5,\"required\":true},{\"name\":\"Certificate of Grades\",\"note\":\"Grades from the previous semester\",\"types\":[\"pdf\",\"jpg\",\"png\"],\"max_mb\":5,\"required\":true}],\"application_route\":\"Apply online through the DOST-SEI scholarship site (science-scholarships.ph), where the forms are posted, then take the DOST-SEI Scholarship Examination. Qualifiers enroll in a priority S&T program at the University of the Philippines, a state college such as DNSC, or a private school that is a CHED Center of Excellence \\/ Development or has FAAP Level III accreditation.\",\"window_note\":\"For Grade 12 students graduating in SY 2025\\u20132026, and earlier Grade 12 graduates not yet enrolled in college. Watch science-scholarships.ph for the call and exam schedule.\",\"application_opens_on\":null,\"application_closes_on\":null,\"results_on\":null,\"official_url\":\"https:\\/\\/www.science-scholarships.ph\\/\",\"rules\":[{\"key\":\"citizen\",\"label\":\"Natural-born Filipino citizen\",\"type\":\"eq\",\"fact\":\"citizenship\",\"value\":\"filipino\",\"required\":true,\"weight\":2,\"src\":\"web\"},{\"key\":\"incoming\",\"label\":\"Graduating from Grade 12, or a Grade 12 graduate not yet enrolled in college\",\"type\":\"eq\",\"fact\":\"enrollment_status\",\"value\":\"incoming_first_year\",\"required\":true,\"weight\":3,\"src\":\"web\"},{\"key\":\"strand\",\"label\":\"STEM strand graduate, or in the top 5% of a non-STEM graduating class\",\"type\":\"confirm\",\"fact\":\"shs_gwa_percent\",\"required\":true,\"weight\":3,\"src\":\"web\",\"confirm_note\":\"Your principal certifies this on Form E (E1 for STEM, E2 for non-STEM top 5%; E3 homeschool; E4 ALS).\"},{\"key\":\"course\",\"label\":\"Enrolling in a DOST-SEI priority S&T program\",\"type\":\"program_in\",\"fact\":\"program_name\",\"required\":true,\"weight\":5,\"src\":\"web\",\"pass\":[\"Bachelor of Science in Agro-Forestry\",\"Bachelor of Science in Fisheries and Aquatic Sciences\",\"Bachelor of Science in Food Technology\",\"Bachelor of Science in Information Systems\",\"Bachelor of Science in Information Technology\",\"Bachelor of Science in Marine Biology\",\"Bachelor of Secondary Education - Mathematics\",\"Bachelor of Secondary Education - Science\"],\"maybe\":[\"Bachelor of Technology and Livelihood Education\"],\"not\":[\"Bachelor of Arts in Communication\",\"Bachelor of Physical Education\",\"Bachelor of Public Administration\",\"Bachelor of Science in Criminology\",\"Bachelor of Science in Disaster Resilience and Management\",\"Bachelor of Science in Entrepreneurship\",\"Bachelor of Science in Social Work\",\"Bachelor of Science in Tourism Management\",\"Bachelor of Secondary Education - English\"]},{\"key\":\"no_units\",\"label\":\"Has not earned any post-secondary (college or vocational) units\",\"type\":\"eq\",\"fact\":\"previous_units\",\"value\":\"no\",\"required\":true,\"weight\":2,\"src\":\"web\"},{\"key\":\"exam\",\"label\":\"DOST-SEI Scholarship Examination taken or passed (selection is by this exam)\",\"type\":\"in\",\"fact\":\"dost_exam\",\"value\":[\"taken_waiting\",\"passed\"],\"required\":false,\"weight\":3,\"src\":\"web\"},{\"key\":\"ra7687\",\"label\":\"RA 7687 track only: family income within DOST\'s set values, and living in your municipality for at least 4 years\",\"type\":\"confirm\",\"fact\":\"income_max\",\"required\":false,\"weight\":1,\"src\":\"web\",\"confirm_note\":\"The Merit track has no income or residency requirement. For RA 7687, DOST-SEI checks your proof of income and your barangay\'s certificate of residency.\"}]}',0,'2026-11-18 09:02:46'),
(2,8,1,'{\"overview\":\"A competitive CHED scholarship for academically talented and deserving incoming or current first-year college students who graduated from a Philippine senior high school with a Grade 12 GWA of at least 93%. CHED Regional Offices evaluate and rank applicants; meeting the requirements does not guarantee a slot.\",\"benefits\":[\"State colleges like DNSC: tuition and other school fees under Free Higher Education\",\"Full scholarship (Full-SSP): \\u20b140,000 per semester (\\u20b180,000 a year) = stipend \\u20b135,000 (\\u20b17,000 a month \\u00d7 5 months) + book \\/ connectivity allowance \\u20b15,000\",\"Half scholarship (Half-SSP): \\u20b120,000 per semester (\\u20b140,000 a year) = stipend \\u20b117,500 (\\u20b13,500 a month \\u00d7 5 months) + book \\/ connectivity allowance \\u20b12,500\",\"Paid every semester until you finish the degree program, if you keep the scholarship\",\"Paid by CHEDRO to your bank account or by check, or through DNSC if it has an agreement with CHEDRO. For the first payment: certified COR \\/ COE, college ID or government ID with your signature, and a copy of an active Landbank ATM card\"],\"documents\":[\"Accomplished application form (Annex A)\",\"Birth certificate issued by the NSO or PSA\",\"Certified true copy of Form 138 (Learner\'s Progress Report Card \\/ SF9), signed by the registrar of your senior high school\",\"Any one: latest ITR of parents or guardian; BIR Certificate of Tax Exemption \\/ Non-Filer; certified latest contract or proof of income (children of OFWs and seafarers); or Social Case Study Report from the C\\/MSWDO\",\"If applicable: PWD ID or PDAO certification; Solo Parent ID; Senior Citizen ID; DHSUD or C\\/MSWDO certification (underprivileged and homeless family); C\\/MSWDO Social Case Study (Magna Carta for the Poor \\/ first-generation students); NCIP certification (Indigenous Peoples)\",\"Notarized Certificate of Guardianship, if applicable\"],\"renewal_requirements\":[{\"name\":\"Certified true copy of the Certificate of Registration \\/ Enrollment (COR \\/ COE)\",\"note\":null,\"types\":[\"pdf\",\"jpg\",\"png\"],\"max_mb\":5,\"required\":true},{\"name\":\"Certified true copy of grades showing the GWA of the previous semester\",\"note\":null,\"types\":[\"pdf\",\"jpg\",\"png\"],\"max_mb\":5,\"required\":true},{\"name\":\"HEI certification that you do not receive another national government-funded scholarship (every start of the academic year)\",\"note\":null,\"types\":[\"pdf\",\"jpg\",\"png\"],\"max_mb\":5,\"required\":true}],\"application_route\":\"Apply to the CHED Regional Office (CHEDRO XI for Davao) with the Annex A form and documents. CHEDRO evaluates and ranks applicants, tells you the result by SMS or e-mail, and issues a Notice of Award (NOA) to qualified applicants or through DNSC.\",\"window_note\":\"CHED announces one call per academic year for incoming and current first-year students. Watch CHED and CHEDRO XI announcements.\",\"application_opens_on\":null,\"application_closes_on\":null,\"results_on\":null,\"official_url\":\"https:\\/\\/ched.gov.ph\\/\",\"rules\":[{\"key\":\"citizen\",\"label\":\"Filipino citizen\",\"type\":\"eq\",\"fact\":\"citizenship\",\"value\":\"filipino\",\"required\":true,\"weight\":2,\"src\":\"web\"},{\"key\":\"first_year\",\"label\":\"Incoming or current first-year college student\",\"type\":\"eq\",\"fact\":\"year_level\",\"value\":1,\"required\":true,\"weight\":3,\"src\":\"web\"},{\"key\":\"gwa\",\"label\":\"Grade 12 GWA of at least 93%\",\"type\":\"gte\",\"fact\":\"shs_gwa_percent\",\"value\":93,\"required\":true,\"weight\":5,\"src\":\"web\"},{\"key\":\"income\",\"label\":\"Combined parent \\/ guardian gross income of \\u20b1500,000 or less\",\"type\":\"income_lte\",\"fact\":\"income\",\"value\":500000,\"required\":true,\"weight\":4,\"src\":\"web\"},{\"key\":\"no_other\",\"label\":\"Not already getting another national government-funded scholarship or grant, including TES or TDP (one-time grants do not count)\",\"type\":\"contains_none\",\"fact\":\"existing_assistance\",\"value\":[\"tes_tdp_ched\",\"other_government\"],\"required\":true,\"weight\":3,\"src\":\"web\"},{\"key\":\"no_degree\",\"label\":\"Has not finished an undergraduate degree (no second-course takers)\",\"type\":\"eq\",\"fact\":\"previous_degree\",\"value\":\"no\",\"required\":true,\"weight\":3,\"src\":\"web\"},{\"key\":\"no_credited_units\",\"label\":\"Not a transferee or shiftee with credited college units\",\"type\":\"eq\",\"fact\":\"previous_units\",\"value\":\"no\",\"required\":true,\"weight\":3,\"src\":\"web\"},{\"key\":\"ph_shs\",\"label\":\"Graduated from a senior high school in the Philippines\",\"type\":\"confirm\",\"fact\":\"shs_gwa_percent\",\"required\":true,\"weight\":1,\"src\":\"web\",\"confirm_note\":\"Your Form 138 from a Philippine senior high school shows this.\"},{\"key\":\"priority\",\"label\":\"Enrolled in a CHED priority program (non-priority programs cannot apply)\",\"type\":\"confirm\",\"fact\":\"program_field\",\"required\":true,\"weight\":3,\"src\":\"web\",\"confirm_note\":\"The program must be on the CHED priority list and have CHED recognition (a Certificate of Program Compliance for state colleges). Ask CHEDRO XI or the DNSC Scholarship and Grants Unit.\"}]}','{\"overview\":\"A competitive CHED scholarship for academically talented and deserving incoming or current first-year college students who graduated from a Philippine senior high school with a Grade 12 GWA of at least 93%. CHED Regional Offices evaluate and rank applicants; meeting the requirements does not guarantee a slot.\",\"benefits\":[\"State colleges like DNSC: tuition and other school fees under Free Higher Education\",\"Full scholarship (Full-SSP): \\u20b140,000 per semester (\\u20b180,000 a year) = stipend \\u20b135,000 (\\u20b17,000 a month \\u00d7 5 months) + book \\/ connectivity allowance \\u20b15,000\",\"Half scholarship (Half-SSP): \\u20b120,000 per semester (\\u20b140,000 a year) = stipend \\u20b117,500 (\\u20b13,500 a month \\u00d7 5 months) + book \\/ connectivity allowance \\u20b12,500\",\"Paid every semester until you finish the degree program, if you keep the scholarship\",\"Paid by CHEDRO to your bank account or by check, or through DNSC if it has an agreement with CHEDRO. For the first payment: certified COR \\/ COE, college ID or government ID with your signature, and a copy of an active Landbank ATM card\"],\"documents\":[\"Accomplished application form (Annex A)\",\"Birth certificate issued by the NSO or PSA\",\"Certified true copy of Form 138 (Learner\'s Progress Report Card \\/ SF9), signed by the registrar of your senior high school\",\"Any one: latest ITR of parents or guardian; BIR Certificate of Tax Exemption \\/ Non-Filer; certified latest contract or proof of income (children of OFWs and seafarers); or Social Case Study Report from the C\\/MSWDO\",\"If applicable: PWD ID or PDAO certification; Solo Parent ID; Senior Citizen ID; DHSUD or C\\/MSWDO certification (underprivileged and homeless family); C\\/MSWDO Social Case Study (Magna Carta for the Poor \\/ first-generation students); NCIP certification (Indigenous Peoples)\",\"Notarized Certificate of Guardianship, if applicable\"],\"renewal_requirements\":[{\"name\":\"Certified true copy of the Certificate of Registration \\/ Enrollment (COR \\/ COE)\",\"note\":null,\"types\":[\"pdf\",\"jpg\",\"png\"],\"max_mb\":5,\"required\":true},{\"name\":\"Certified true copy of grades showing the GWA of the previous semester\",\"note\":null,\"types\":[\"pdf\",\"jpg\",\"png\"],\"max_mb\":5,\"required\":true},{\"name\":\"HEI certification that you do not receive another national government-funded scholarship (every start of the academic year)\",\"note\":null,\"types\":[\"pdf\",\"jpg\",\"png\"],\"max_mb\":5,\"required\":true}],\"application_route\":\"Apply to the CHED Regional Office (CHEDRO XI for Davao) with the Annex A form and documents. CHEDRO evaluates and ranks applicants, tells you the result by SMS or e-mail, and issues a Notice of Award (NOA) to qualified applicants or through DNSC.\",\"window_note\":\"CHED announces one call per academic year for incoming and current first-year students. Watch CHED and CHEDRO XI announcements.\",\"application_opens_on\":null,\"application_closes_on\":null,\"results_on\":null,\"official_url\":\"https:\\/\\/ched.gov.ph\\/\",\"rules\":[{\"key\":\"citizen\",\"label\":\"Filipino citizen\",\"type\":\"eq\",\"fact\":\"citizenship\",\"value\":\"filipino\",\"required\":true,\"weight\":2,\"src\":\"web\"},{\"key\":\"first_year\",\"label\":\"Incoming or current first-year college student\",\"type\":\"eq\",\"fact\":\"year_level\",\"value\":1,\"required\":true,\"weight\":3,\"src\":\"web\"},{\"key\":\"gwa\",\"label\":\"Grade 12 GWA of at least 93%\",\"type\":\"gte\",\"fact\":\"shs_gwa_percent\",\"value\":93,\"required\":true,\"weight\":5,\"src\":\"web\"},{\"key\":\"income\",\"label\":\"Combined parent \\/ guardian gross income of \\u20b1500,000 or less\",\"type\":\"income_lte\",\"fact\":\"income\",\"value\":500000,\"required\":true,\"weight\":4,\"src\":\"web\"},{\"key\":\"no_other\",\"label\":\"Not already getting another national government-funded scholarship or grant, including TES or TDP (one-time grants do not count)\",\"type\":\"contains_none\",\"fact\":\"existing_assistance\",\"value\":[\"tes_tdp_ched\",\"other_government\"],\"required\":true,\"weight\":3,\"src\":\"web\"},{\"key\":\"no_degree\",\"label\":\"Has not finished an undergraduate degree (no second-course takers)\",\"type\":\"eq\",\"fact\":\"previous_degree\",\"value\":\"no\",\"required\":true,\"weight\":3,\"src\":\"web\"},{\"key\":\"no_credited_units\",\"label\":\"Not a transferee or shiftee with credited college units\",\"type\":\"eq\",\"fact\":\"previous_units\",\"value\":\"no\",\"required\":true,\"weight\":3,\"src\":\"web\"},{\"key\":\"ph_shs\",\"label\":\"Graduated from a senior high school in the Philippines\",\"type\":\"confirm\",\"fact\":\"shs_gwa_percent\",\"required\":true,\"weight\":1,\"src\":\"web\",\"confirm_note\":\"Senior High School grades shows this.\"},{\"key\":\"priority\",\"label\":\"Enrolled in a CHED priority program (non-priority programs cannot apply)\",\"type\":\"confirm\",\"fact\":\"program_field\",\"required\":true,\"weight\":3,\"src\":\"web\",\"confirm_note\":\"The program must be on the CHED priority list and have CHED recognition. Ask CHEDRO XI or the DNSC Scholarship and Grants Unit.\"}]}',1,'2026-11-18 22:50:25'),
