(10,5,1,'{\"overview\":\"A CHED-UniFAST grant for Filipino students taking their first undergraduate degree in a state, local or private college that is in the CHED Registry and has an agreement (MOA) with CHED-UniFAST. Qualifying does not guarantee a grant: CHED cross-checks all applicants and releases the final list of qualified grantees.\",\"benefits\":[\"\\u20b17,500 per semester (\\u20b115,000 per academic year), for new and continuing grantees\",\"The amount may be increased if the UniFAST Board approves\",\"Continuing grantees do not re-apply; they keep the grant up to the Maximum Residency Rule\",\"Paid by direct credit to your account, by check, or through DNSC, which must release it within 15 working days of receiving the funds\"],\"documents\":[\"Scanned TDP Application Form\",\"Certificate of Registration \\/ Enrollment (COR \\/ COE), PDF copy\",\"Certificate of Indigency issued by the Punong Barangay where you live (if it cannot be secured: Certificate of Tax Exemption, or a Social Case Study from a registered social worker)\"],\"renewal_requirements\":[{\"name\":\"Certificate of Registration \\/ Enrollment (COR \\/ COE), PDF copy, for the current semester (or your name on DNSC\'s certified Enrollment List)\",\"note\":null,\"types\":[\"pdf\"],\"max_mb\":5,\"required\":true},{\"name\":\"If returning after a one-term Leave of Absence: the LOA you submitted to DNSC (PDF copy)\",\"note\":null,\"types\":[\"pdf\"],\"max_mb\":5,\"required\":false},{\"name\":\"If you transferred from another school: COR \\/ COE of the previous and the current semester (PDF copies)\",\"note\":null,\"types\":[\"pdf\"],\"max_mb\":5,\"required\":false},{\"name\":\"If you submit directly to CHEDRO: a school ID or government-issued ID with your specimen signature (PDF copy)\",\"note\":null,\"types\":[\"pdf\"],\"max_mb\":5,\"required\":false}],\"application_route\":\"After DNSC\'s enrollment period, the UniFAST Secretariat issues a call. Submit the application and documents through the partner implementer (DNSC) or directly to the CHED Regional Office (CHEDRO). CHEDRO uploads applications to the RC Portal, cross-checks for duplicate grants, and releases the list of qualified applicants to DNSC.\",\"window_note\":\"The call opens after DNSC\'s enrollment period each semester. These guidelines apply from the 1st Semester of AY 2026-2027.\",\"application_opens_on\":null,\"application_closes_on\":null,\"results_on\":null,\"official_url\":\"https:\\/\\/unifast.gov.ph\\/\",\"scholar_id_format\":\"SCID-0000-0000\",\"rules\":[{\"key\":\"citizen\",\"label\":\"Filipino citizen\",\"type\":\"eq\",\"fact\":\"citizenship\",\"value\":\"filipino\",\"required\":true,\"weight\":2,\"src\":\"web\"},{\"key\":\"first_degree\",\"label\":\"Taking a first undergraduate degree (no previous bachelor\'s degree)\",\"type\":\"eq\",\"fact\":\"previous_degree\",\"value\":\"no\",\"required\":true,\"weight\":3,\"src\":\"web\"},{\"key\":\"enrolled\",\"label\":\"Enrolled at DNSC (the call opens after the enrollment period)\",\"type\":\"in\",\"fact\":\"enrollment_status\",\"value\":[\"currently_enrolled\",\"incoming_first_year\"],\"required\":true,\"weight\":1,\"src\":\"web\"},{\"key\":\"mrr\",\"label\":\"Within the Maximum Residency Rule (the normal length of the program plus one year)\",\"type\":\"eq\",\"fact\":\"within_years\",\"value\":\"yes\",\"required\":true,\"weight\":2,\"src\":\"web\",\"skip_if\":{\"enrollment_status\":\"incoming_first_year\"}},{\"key\":\"no_other\",\"label\":\"Not receiving another national government-funded financial assistance (Free Higher Education and one-time grants such as AICS or SMART do not count, but TDP and SMART cannot be received in the same semester)\",\"type\":\"contains_none\",\"fact\":\"existing_assistance\",\"value\":[\"tes_tdp_ched\",\"other_government\"],\"required\":true,\"weight\":3,\"src\":\"web\"},{\"key\":\"indigency\",\"label\":\"Can get a Certificate of Indigency from your barangay\",\"type\":\"confirm\",\"fact\":\"income_max\",\"required\":true,\"weight\":4,\"src\":\"web\",\"confirm_note\":\"Ask the Punong Barangay where you live. If it cannot be secured, a Certificate of Tax Exemption or a Social Case Study from a registered social worker is accepted.\"},{\"key\":\"retention\",\"label\":\"Meets DNSC admission and retention policies\",\"type\":\"confirm\",\"fact\":\"dnsc_student\",\"required\":false,\"weight\":1,\"src\":\"web\",\"confirm_note\":\"DNSC and the CHED Regional Office check this when they validate your enrollment.\"},{\"key\":\"slots\",\"label\":\"A TDP call is open at DNSC this semester\",\"type\":\"confirm\",\"fact\":\"dnsc_student\",\"required\":false,\"weight\":1,\"src\":\"web\",\"confirm_note\":\"The UniFAST Secretariat issues the call after the enrollment period. Ask the DNSC Scholarship and Grants Unit.\"}]}','{\"overview\":\"A CHED-UniFAST grant for Filipino students taking their first undergraduate degree in a state, local or private college that is in the CHED Registry and has an agreement (MOA) with CHED-UniFAST. Qualifying does not guarantee a grant: CHED cross-checks all applicants and releases the final list of qualified grantees.\",\"benefits\":[\"\\u20b17,500 per semester (\\u20b115,000 per academic year), for new and continuing grantees\",\"The amount may be increased if the UniFAST Board approves\",\"Continuing grantees do not re-apply; they keep the grant up to the Maximum Residency Rule\",\"Paid by direct credit to your account, by check, or through DNSC, which must release it within 15 working days of receiving the funds\"],\"documents\":[\"Scanned TDP Application Form\",\"Certificate of Registration \\/ Enrollment (COR \\/ COE), PDF copy\",\"Certificate of Indigency issued by the Punong Barangay where you live (if it cannot be secured: Certificate of Tax Exemption, or a Social Case Study from a registered social worker)\"],\"renewal_requirements\":[{\"name\":\"Certificate of Registration \\/ Enrollment (COR \\/ COE), PDF copy, for the current semester (or your name on DNSC\'s certified Enrollment List)\",\"note\":null,\"types\":[\"pdf\"],\"max_mb\":5,\"required\":true},{\"name\":\"If returning after a one-term Leave of Absence: the LOA you submitted to DNSC (PDF copy)\",\"note\":null,\"types\":[\"pdf\"],\"max_mb\":5,\"required\":false},{\"name\":\"If you transferred from another school: COR \\/ COE of the previous and the current semester (PDF copies)\",\"note\":null,\"types\":[\"pdf\"],\"max_mb\":5,\"required\":false},{\"name\":\"If you submit directly to CHEDRO: a school ID or government-issued ID with your specimen signature (PDF copy)\",\"note\":null,\"types\":[\"pdf\"],\"max_mb\":5,\"required\":false}],\"application_route\":\"After DNSC\'s enrollment period, the UniFAST Secretariat issues a call. Submit the application and documents through the partner implementer (DNSC) or directly to the CHED Regional Office (CHEDRO). CHEDRO uploads applications to the RC Portal, cross-checks for duplicate grants, and releases the list of qualified applicants to DNSC.\",\"window_note\":\"The call opens after DNSC\'s enrollment period each semester. These guidelines apply from the 1st Semester of AY 2026-2027.\",\"application_opens_on\":null,\"application_closes_on\":null,\"results_on\":null,\"official_url\":\"https:\\/\\/unifast.gov.ph\\/\",\"scholar_id_format\":\"HEI-000-000-000\",\"rules\":[{\"key\":\"citizen\",\"label\":\"Filipino citizen\",\"type\":\"eq\",\"fact\":\"citizenship\",\"value\":\"filipino\",\"required\":true,\"weight\":2,\"src\":\"web\"},{\"key\":\"first_degree\",\"label\":\"Taking a first undergraduate degree (no previous bachelor\'s degree)\",\"type\":\"eq\",\"fact\":\"previous_degree\",\"value\":\"no\",\"required\":true,\"weight\":3,\"src\":\"web\"},{\"key\":\"enrolled\",\"label\":\"Enrolled at DNSC (the call opens after the enrollment period)\",\"type\":\"in\",\"fact\":\"enrollment_status\",\"value\":[\"currently_enrolled\",\"incoming_first_year\"],\"required\":true,\"weight\":1,\"src\":\"web\"},{\"key\":\"mrr\",\"label\":\"Within the Maximum Residency Rule (the normal length of the program plus one year)\",\"type\":\"eq\",\"fact\":\"within_years\",\"value\":\"yes\",\"required\":true,\"weight\":2,\"src\":\"web\",\"skip_if\":{\"enrollment_status\":\"incoming_first_year\"}},{\"key\":\"no_other\",\"label\":\"Not receiving another national government-funded financial assistance (Free Higher Education and one-time grants such as AICS or SMART do not count, but TDP and SMART cannot be received in the same semester)\",\"type\":\"contains_none\",\"fact\":\"existing_assistance\",\"value\":[\"tes_tdp_ched\",\"other_government\"],\"required\":true,\"weight\":3,\"src\":\"web\"},{\"key\":\"indigency\",\"label\":\"Can get a Certificate of Indigency from your barangay\",\"type\":\"confirm\",\"fact\":\"income_max\",\"required\":true,\"weight\":4,\"src\":\"web\",\"confirm_note\":\"Ask the Punong Barangay where you live. If it cannot be secured, a Certificate of Tax Exemption or a Social Case Study from a registered social worker is accepted.\"},{\"key\":\"retention\",\"label\":\"Meets DNSC admission and retention policies\",\"type\":\"confirm\",\"fact\":\"dnsc_student\",\"required\":false,\"weight\":1,\"src\":\"web\",\"confirm_note\":\"DNSC and the CHED Regional Office check this when they validate your enrollment.\"},{\"key\":\"slots\",\"label\":\"A TDP call is open at DNSC this semester\",\"type\":\"confirm\",\"fact\":\"dnsc_student\",\"required\":false,\"weight\":1,\"src\":\"web\",\"confirm_note\":\"The UniFAST Secretariat issues the call after the enrollment period. Ask the DNSC Scholarship and Grants Unit.\"}]}',0,'2026-11-19 08:50:13'),
(11,5,1,'{\"overview\":\"A CHED-UniFAST grant for Filipino students taking their first undergraduate degree in a state, local or private college that is in the CHED Registry and has an agreement (MOA) with CHED-UniFAST. Qualifying does not guarantee a grant: CHED cross-checks all applicants and releases the final list of qualified grantees.\",\"benefits\":[\"\\u20b17,500 per semester (\\u20b115,000 per academic year), for new and continuing grantees\",\"The amount may be increased if the UniFAST Board approves\",\"Continuing grantees do not re-apply; they keep the grant up to the Maximum Residency Rule\",\"Paid by direct credit to your account, by check, or through DNSC, which must release it within 15 working days of receiving the funds\"],\"documents\":[\"Scanned TDP Application Form\",\"Certificate of Registration \\/ Enrollment (COR \\/ COE), PDF copy\",\"Certificate of Indigency issued by the Punong Barangay where you live (if it cannot be secured: Certificate of Tax Exemption, or a Social Case Study from a registered social worker)\"],\"renewal_requirements\":[{\"name\":\"Certificate of Registration \\/ Enrollment (COR \\/ COE), PDF copy, for the current semester (or your name on DNSC\'s certified Enrollment List)\",\"note\":null,\"types\":[\"pdf\"],\"max_mb\":5,\"required\":true},{\"name\":\"If returning after a one-term Leave of Absence: the LOA you submitted to DNSC (PDF copy)\",\"note\":null,\"types\":[\"pdf\"],\"max_mb\":5,\"required\":false},{\"name\":\"If you transferred from another school: COR \\/ COE of the previous and the current semester (PDF copies)\",\"note\":null,\"types\":[\"pdf\"],\"max_mb\":5,\"required\":false},{\"name\":\"If you submit directly to CHEDRO: a school ID or government-issued ID with your specimen signature (PDF copy)\",\"note\":null,\"types\":[\"pdf\"],\"max_mb\":5,\"required\":false}],\"application_route\":\"After DNSC\'s enrollment period, the UniFAST Secretariat issues a call. Submit the application and documents through th